
#include "viceroy_types.h"
#include "power.h"

#define REL_FLAG_WAR            0x02
#define REL_FLAG_PEACE_PENDING  0x20
#define REL_FLAG_TREATY         0x40

#define REL_STATE_BASE   g_treaty_matrix_base
#define POWER_STRIDE     0x13C
#define REL_STATE_NONE   0
#define REL_STATE_TREATY 1

extern uint8_t rel_query(int power_self, int power_other);

uint8_t rel_state_get(int power_self, int power_other)
{

    const uint8_t *base = (const uint8_t *)REL_STATE_BASE;
    return base[(unsigned)power_self * POWER_STRIDE + (unsigned)power_other];
}

int rel_at_war(int self, int other)        { return (rel_query(self, other) & REL_FLAG_WAR)   != 0; }
int rel_has_treaty(int self, int other)    { return (rel_query(self, other) & REL_FLAG_TREATY)!= 0; }
int rel_peace_pending(int self, int other) { return (rel_query(self, other) & REL_FLAG_PEACE_PENDING) != 0; }

#define WAR_FLAG_MATRIX_BASE  g_war_matrix_base
#define WAR_FLAG_AT_WAR       0x02

extern void rel_clear_event(int mask, int power_a, int handle);
extern int  power_handle(int power_idx);

static inline uint8_t *war_flag_cell(int power_self, int power_other)
{
    uint8_t *base = (uint8_t *)WAR_FLAG_MATRIX_BASE;
    return base + (unsigned)power_self * POWER_STRIDE + (unsigned)power_other;
}

void rel_declare_war(int attacker, int defender)
{

    if (rel_query(attacker, defender) & REL_FLAG_TREATY) {
        *war_flag_cell(attacker, defender) |= WAR_FLAG_AT_WAR;
    }

    rel_clear_event(REL_FLAG_TREATY, defender, power_handle(defender));

    *war_flag_cell(defender, attacker) &= (uint8_t)0xFE;
}

