void rt_code_select_2out(uint16_t code, uint16_t *out_glyph, uint16_t *out_attr)
{
    uint16_t g;
    switch (code - 1) {
    case 0:
    case 1:  g = 0x95; break;
    case 2:  g = 0x0C; break;
    default: g = 0x44; break;
    }
    *out_glyph = g;
    *out_attr  = 0x22;
}

