void format_to_buffer_2D54(const char *src)
{

    char *dst = (char *)&DG8(0x2D54);
    unsigned len = 0;
    while (dst[len]) len++;
    if (src) {
        while (*src && len < 0xFF) dst[len++] = *src++;
    }

    {
        const char *sep = (const char *)&DG8(0x004D);
        while (*sep && len < 0xFF) dst[len++] = *sep++;
    }
    dst[len] = 0;
}

