static inline uint8_t *war_flag_cell(int self, int other)
{
    uint8_t *base = (uint8_t *)WAR_FLAG_MATRIX_BASE;
    return base + (unsigned)self * POWER_STRIDE + (unsigned)other;
}
static inline int32_t *power_gold(int power_idx)
{
    uint8_t *base = (uint8_t *)POWER_TABLE_BASE;
    return (int32_t *)(base + (unsigned)power_idx * POWER_STRIDE + POWER_GOLD_LO_OFF);
}

static inline int32_t *power_gold_active(void)
{
    return (int32_t *)((uint8_t *)g_active_power + POWER_GOLD_LO_OFF);
}

void diplomacy_meeting(int power_self, int power_other, int ctx, void *rec, int mode)
{
    int  score = 0;
    int  want_action = 0;
    int  warbit_set;
    int  is_war_topic = 0;
    int  third_power = -1;
    int  notify_kind = 0;
    int  dlg;
    char buf[0x54];
    char buf2[0x2c];

    (void)ctx; (void)rec; (void)mode; (void)buf2;

    if (power_self < 4 && g_perpower_flag_543F[power_self * 0x34] != 0) {
        diplo_native_meeting(power_other, power_self);
        return;
    }
    if (g_diplo_guard_5382 & 1)
        return;

    if (!(rel_query(power_self, power_other) & 0x20)) {
        want_action = 1;

    }
    {
        int16_t *timer = (int16_t *)((uint8_t *)TREATY_TIMER_BASE + power_other * 2);
        if (*timer + 0x10 > *(int16_t *)TURN_COUNTER) {
            want_action = 1;
            rel_clear_event(0x10, power_self, power_other);
        }
    }

    warbit_set = *war_flag_cell(power_self, power_other) & WAR_FLAG_AT_WAR;

    if (score != 0 && notify_kind == 1
        && *power_gold_active() >= (int32_t)score) {

        dlg = ui_dialog_show(power_other, (int)buf);
        if (dlg == 2) {
            *power_gold_active()    -= (int32_t)score;
            *power_gold(power_other) += (int32_t)score;
            want_action = 0;
        }
        score = 0x3E7;
    }

    if (notify_kind != 0 && score != 0x3E7 ) {

        dlg = ui_dialog_show(power_other, (int)buf);
        if (dlg == 2) {

            want_action = 0;
        }
    }

    if (want_action && (rel_query(power_self, power_other) & 0x40)
        && score > 0x64) {
        ui_dialog_show(power_other, DK_PROVOKE);
        rel_clear_event(0x40, power_self, power_other);
    }

    if (want_action == 0) {

        if (!(rel_query(power_self, power_other) & 0x40)) {

            dlg = ui_dialog_show(power_other, DK_WORTHY);
            if (dlg == 1) {
                rel_apply_event(0x40, power_other, power_self);
                {
                    int16_t *timer = (int16_t *)((uint8_t *)TREATY_TIMER_BASE + power_other * 2);
                    *timer = *(int16_t *)TURN_COUNTER + 0x10;
                }

            }
        }

        if (warbit_set == 0) {
            int  payment;
            long g = gold_scale_0D1D_0EC6(
                        (int)((uint32_t)*power_gold(power_other) >> 16),
                        (int)((uint32_t)*power_gold(power_other) & 0xFFFF),
                        0, 0);

            payment = (int)diplo_scale_181F_035C(g, 0, 0);

            payment = payment * 0x64;
            if (payment != 0) {

                dlg = ui_dialog_show(power_other, (int)buf);
                if (dlg == 1) {
                    rel_apply_event(0x40, power_other, power_self);

                    *power_gold(power_other) -= (int32_t)payment;
                    *power_gold_active()     += (int32_t)payment;
                }
            }
        }
    }

    if (rel_query(power_self, power_other) & 0x40) {
        diplo_relation_tag(power_other, power_self);
        diplo_relation_tag(power_self, power_other);
    }
    if (want_action)
        goto present_screen;

present_screen:

    return;
}

