int func_004314_colony_blit(uint16_t idx, int sx, int sy,
                            uint16_t name_flag, uint16_t pop_flag,
                            uint16_t metric)
{
    int rec = (int)idx * 0xCA;
    int owner = DG8(rec + COL_OWNER_5D60);
    int pop   = DG8(rec + g_colony_table__population);
    int level = 0, variant;
    char buf[40];

    for (int a = 0; a < 3; a++)
        if (func_00860E_logic_sz_15(idx, (uint16_t)a)) level++;
    variant = level;

    if (owner != (int16_t)DG16(g_active_human_player) && DG16(0x53A2) == 0) {
        int pw = (int16_t)DG16(g_active_human_player);
        variant = (DG8(rec + pw + g_colony_table__stockpile_9a[18]) - 1) & 3;
        pop = DG8(rec + pw + g_colony_table__stockpile_9a[16]);
        if (pop == 0) {
            pop = 1;
            DG8(rec + (int16_t)DG16(g_active_human_player) + g_colony_table__stockpile_9a[16]) = 1;
        }
    }

    int dxw;
    if ((int16_t)metric < 0x64) {
        sx -= 2 >> (int16_t)DG16(0x0184);
        dxw = (int16_t)DG16(G_TILE_PX);
    } else dxw = 0x10;

    int cy   = (dxw >> 1) + sx;
    int cx2  = dxw + sy - 1;
    int lx, ly;
    if ((int16_t)metric == 0x64) { ly = sx + 6; lx = sy + 4; }
    else                         { ly = sx + 3; lx = sy + 2; }

    vid_cell_blit(variant + 1, cy, cx2, metric, cx2);

    int flag = owner;
    if ((DG8(g_game_phase_flags) & 1) && (int16_t)DG16(g_self_power_idx) == owner)
        flag = (int16_t)DG16(g_current_player);
    int cell = flag + 0x77;
    if ((DG8(g_game_phase_flags) & 1) && (int16_t)DG16(g_current_player) == owner)
        cell = 0x83;
    vid_cell_blit(cell, ly, lx, metric, cx2);

    if ((int16_t)metric == 0x64) {
        int tc = 0xF;
        if (DG8(rec + COL_FLAG_TABLE_5D62) & 4) {
            tc = 0xA;
            if (DG8(rec + COL_FLAG_TABLE_5D62) & 2) tc = 0xB;
        }
        vid_text_color(tc);
        if (pop_flag) {
            snprintf(buf, sizeof buf, "%d", pop);
            vid_text_xy(buf, sx + 7, sy + 7);
        }
        if (name_flag) {
            vid_text_color(0xF);
            vid_text_xy((const char *)&DG8(rec + g_colony_table__name[0]), sx + 2, sy + 0x10);
        }
    }
    if ((int16_t)metric <= 0x19)
        vid_small_box(sx, sy, (int16_t)DG16(G_TILE_PX), DG8(owner + 0x848));
    return 0;
}

