#define SAVE_NAME_STEM   "COLONY"
#define SAVE_NAME_EXT    ".SAV"
#define SAVE_MAGIC       "COLONIZE"
#define SAVE_MODE_W      "wb"
#define SAVE_MAGIC_TERM  0x1A

#define UNIT_STRIDE      0x1C
#define COLONY_STRIDE    0xCA
#define POWER_BYTES      0x4F0
#define POWER_STRIDE     0x13C
#define NATIVE_STRIDE    0x12

extern uint8_t  g_unit_table[];
extern uint8_t  g_colony_table[];
extern uint8_t  g_power_table[];
extern uint8_t  g_native_table[];

