#include "viceroy_types.h"
#include "globals.h"
#include "unit.h"

extern uint8_t  g_units_3144[];

extern int16_t  g_selected_unit_5392;

extern uint8_t  g_power_unit_count_7304[];

extern uint8_t  g_table_54EF[];

#define U_OFF(idx, k)  g_units_3144[(idx) * UNIT_RECORD_STRIDE + (k)]
#define U_MAPX   0x00
#define U_MAPY   0x01
#define U_TYPE   0x02
#define U_OWNER  0x03
#define U_MOVES  0x06
#define U_PROF   0x07
#define U_ORDERS 0x08
#define U_CARGON 0x0C
#define U_PREV   0x18
#define U_NEXT   0x1A

static int16_t u_word(int idx, int k)
{
    return (int16_t)(U_OFF(idx, k) | (U_OFF(idx, k + 1) << 8));
}
static void u_word_set(int idx, int k, int16_t v)
{
    U_OFF(idx, k)     = (uint8_t)(v & 0xFF);
    U_OFF(idx, k + 1) = (uint8_t)((v >> 8) & 0xFF);
}

extern void    ovly_unit_spawned_181F_894(int16_t new_idx, int16_t arg_c);

extern void    ovly_unit_init_181F_844(int16_t idx, int16_t dx_arg, int16_t bx_arg);

extern int     unit_tile_head(int x, int y);
extern int16_t map_tile_set_occupant_037F_0A(int16_t x, int16_t y);

extern void    map_tile_set_head_037F_15E(int16_t x, int16_t y, int16_t mask, int16_t set);
extern int16_t map_tile_reveal_037F_598(int16_t x, int16_t y);

extern void    map_tile_notify_037F_228(int16_t x, int16_t y, int16_t owner);

int16_t unit_create(int16_t kind_flag, int16_t arg_b, int16_t arg_a, int16_t arg_c)
{
    int16_t idx;
    uint8_t type;

    idx = (int16_t)g_unit_count_539C;
    g_unit_count_539C++;
    ovly_unit_spawned_181F_894(idx, arg_c);

    U_OFF(idx, U_MAPX) = 0xFF;
    U_OFF(idx, U_MAPY) = 0xFF;

    type = (kind_flag != 0) ? 0x0D : 0x00;
    U_OFF(idx, U_TYPE)   = type;
    U_OFF(idx, U_MOVES)  = 0xFF;
    U_OFF(idx, U_CARGON) = 0x00;

    ovly_unit_init_181F_844(idx, arg_b, arg_a);
    return idx;
}

void unit_place_on_tile(int16_t unit_idx, int16_t x, int16_t y)
{
    int16_t old_head;
    uint8_t owner;

    old_head = (int16_t)unit_tile_head(x, y);
#ifdef _VICEROY_MODERN
    { extern void tilehead_set(int,int,int);
      tilehead_set(x, y, unit_idx); }
#endif

    U_OFF(unit_idx, U_MAPX) = (uint8_t)x;
    U_OFF(unit_idx, U_MAPY) = (uint8_t)y;
    u_word_set(unit_idx, U_PREV, -1);
    u_word_set(unit_idx, U_NEXT, old_head);

    if (old_head >= 0) {
        u_word_set(old_head, U_PREV, unit_idx);
        return;
    }

    if (map_tile_set_occupant_037F_0A(x, y) == 0)
        return;

    map_tile_set_head_037F_15E(x, y, 1, 1);

    owner = U_OFF(unit_idx, U_OWNER) & 0x0F;
    if (owner >= 4) {
        if (map_tile_reveal_037F_598(x, y) != 0)
            return;
    }
    owner = U_OFF(unit_idx, U_OWNER) & 0x0F;
    map_tile_notify_037F_228(x, y, owner);

}

void unit_chain_unlink(int16_t unit_idx)
{
    int linked = 0;
    int16_t prev, next;
#ifdef _VICEROY_MODERN
    { extern int tilehead_get(int,int); extern void tilehead_set(int,int,int);
      int ux = U_OFF(unit_idx, U_MAPX), uy = U_OFF(unit_idx, U_MAPY);
      if (tilehead_get(ux, uy) == unit_idx)
          tilehead_set(ux, uy, (int16_t)u_word(unit_idx, U_NEXT)); }
#endif

    prev = u_word(unit_idx, U_PREV);
    if (prev >= 0) {
        next = u_word(unit_idx, U_NEXT);
        u_word_set(prev, U_NEXT, next);
        linked = 1;
    }
    next = u_word(unit_idx, U_NEXT);
    if (next >= 0) {
        prev = u_word(unit_idx, U_PREV);
        u_word_set(next, U_PREV, prev);
        linked = 1;
    }

    if (linked == 0) {

        if (map_tile_set_occupant_037F_0A(U_OFF(unit_idx, U_MAPX),
                                          U_OFF(unit_idx, U_MAPY)) != 0) {
            map_tile_set_head_037F_15E(U_OFF(unit_idx, U_MAPX),
                                       U_OFF(unit_idx, U_MAPY),
                                       1, 0);

        }
    }

    U_OFF(unit_idx, U_MAPX) = 0xFF;
    U_OFF(unit_idx, U_MAPY) = 0xFF;
}

void unit_destroy(int16_t unit_idx)
{
    int idx = unit_idx;
    uint8_t owner;
    int new_count;
    int i;

    if (idx < 0)
        return;

    owner = U_OFF(idx, U_OWNER) & 0x0F;
    if (owner < 4) {
        if (g_power_unit_count_7304[owner] != 0)
            g_power_unit_count_7304[owner]--;
    } else {

        if ((int8_t)U_OFF(idx, U_MOVES) >= 0) {
            int k = (int8_t)U_OFF(idx, U_MOVES) * 0x12;
            g_table_54EF[k] |= 1;
        }
    }

    unit_chain_unlink((int16_t)idx);

    new_count = (int)g_unit_count_539C - 1;
    if (new_count > idx) {
        int n = (int)g_unit_count_539C - idx - 1;

        int dst = idx * UNIT_RECORD_STRIDE;
        int j;
        for (j = 0; j < n; j++) {
            int s;
            for (s = 0; s < UNIT_RECORD_STRIDE; s++)
                g_units_3144[dst + j * UNIT_RECORD_STRIDE + s] =
                    g_units_3144[dst + (j + 1) * UNIT_RECORD_STRIDE + s];
        }
    }

    g_unit_count_539C--;

    new_count = (int)g_unit_count_539C;
    for (i = 0; i < new_count; i++) {
        int16_t p = u_word(i, U_PREV);
        int16_t nx = u_word(i, U_NEXT);
        if (p > idx)  u_word_set(i, U_PREV, (int16_t)(p - 1));
        if (nx > idx) u_word_set(i, U_NEXT, (int16_t)(nx - 1));
    }

    if (g_selected_unit_5392 != 0) {
        if (idx <= g_selected_unit_5392)
            g_selected_unit_5392--;
    }
}

