int count_building_chain_present(int start_idx)
{
    int tally = 0;
    int idx = start_idx;
    for (;;) {
        if (test_building_or_father_bit(idx))
            tally++;
        int next = g_chain_next(idx);
        if (next < 0) break;
        idx = next;
    }
    return tally;
}

