int test_bit_at_8a(int bit_idx)
{
    return (ctx->bits_at_8a[bit_idx >> 3] & (1u << (bit_idx & 7))) != 0;
}

void set_or_clear_bit_at_8a(int bit_idx, int set_flag)
{
    uint8_t *p = &ctx->bits_at_8a[bit_idx >> 3];
    uint8_t mask = 1u << (bit_idx & 7);
    if (set_flag) *p |=  mask;
    else          *p &= ~mask;
}

