void colony_auto_manage(int colony_index)
{

    int  is_capital;
    int  ncol_owned;
    int  ring_n;
    int  owner;
    int  i;
    uint8_t *col;

    colony_select(colony_index);
    col = (uint8_t *)g_colony_buf_8542;

    is_capital = (col[0] == 0x2e && col[1] == 0x14) ? 1 : 0;

    crt_memset(col + 0x8a, 0, 2);

    colony_helper_C22();
    ncol_owned = colony_helper_C5E_count();

    ring_n     = DG8(0x329 + (unsigned)(uint16_t)func_008720());

    col = (uint8_t *)g_colony_buf_8542;
    if ((int8_t)col[0x8c] < 0x7f) col[0x8c]++;
    if ((int8_t)col[0x8f] < 0x7f) col[0x8f]++;

    owner = col[0x1a];
    (void)map_index(col[1], col[0]);

    {
        int s = sol_pct();
        int rank = ((100 - s) * (int8_t)col[0x1f] + 0x32) / 100;
        if (g_war_flags_5382 & 1) rank = 0;
        (void)rank;

    }

    col = (uint8_t *)g_colony_buf_8542;
    {

    }

    col = (uint8_t *)g_colony_buf_8542;
    col[0x1b] &= 7;
    if ((col[0x1c] & 0x10) && (int8_t)col[0x1f] < 0x20) {
        col[0x1b] |= 0x10;
        col[0x1c] &= 0xef;
    }
    if (defense_cnt_pos())
        col[0x1b] |= 0x40;

    col = (uint8_t *)g_colony_buf_8542;

    {
        int v = colony_owner_val(col[0x1a]);
        (void)v;
    }

    crt_memset(&_hist_a, 0, 0x32);
    crt_memset(&_hist_b, 0, 0x32);

    slot_commit();
    col = (uint8_t *)g_colony_buf_8542;

    col = (uint8_t *)g_colony_buf_8542;
    if (defense_cnt_le0() &&
        *(int16_t *)(col + 0xb8) >= 0xC8) {
        uint8_t *kr = (uint8_t *)g_king_record_84FC;
        if (kr[0x49] < 0x14) {
            kr[0x49]++;
            *(int16_t *)(col + 0xb8) -= 0x32;
        }
    }
    g_flag_034C = 0;
    helper_BD2();

    if (!(col[0x1b] & 0x80) &&
        (g_event_turn_538E % 10) == 0 &&
        build_flag_set()) {
        uint8_t *kr = (uint8_t *)g_king_record_84FC;
        int idx = col[0x1a];
        uint32_t cost = (uint32_t)0x14 *
            ((uint8_t *)DGROUP_PTR(KING_COST_84CA))[idx << 4];
        uint32_t treasury = ((uint16_t *)kr)[0x2a / 2] |
                            ((uint32_t)((uint16_t *)kr)[0x2c / 2] << 16);
        if (treasury >= cost) {
            ((uint16_t *)kr)[0x2a / 2] -= (uint16_t)cost;
            ((uint16_t *)kr)[0x2c / 2] -= (uint16_t)(cost>>16);
            building_finished_fx(0x14, 0xE);
            col = (uint8_t *)g_colony_buf_8542;
            *(int16_t *)(col + 0xb6) += 0x14;

        }
    }

    col = (uint8_t *)g_colony_buf_8542;

    {

        int x = 0, y = 0;
        int nu = place_colonist(0, col[0x1a], x, y, g_byte_524E);
        if (nu >= 0) {
            uint8_t *u = (uint8_t *)DGROUP_PTR(UNIT_BASE_3144 + nu * UNIT_STRIDE_1C);
            u[U_TURN_315A - UNIT_BASE_3144] = 0x63;
        }
    }

    col = (uint8_t *)g_colony_buf_8542;
    for (i = 0; i < (int8_t)col[0x1f]; i++) {
        int occ = slot_get_a(i);

        helper_BB4(i);
        assign_job(0x12, i);
        (void)occ;
    }
    for (i = 0; i < 0x14; i++)
        col[0x70 + i] = 0xff;

    crt_memset(col + 0x70, -1, 0x14);
    slot_advance();

    g_result_flag_035E = 1;

    col = (uint8_t *)g_colony_buf_8542;
    col[0x1d] &= 0x7f;
    col[0x94] = 0xff;

    col = (uint8_t *)g_colony_buf_8542;
    if (*(int16_t *)(col + 0xaa) < 2 &&
        g_event_turn_538E >= 0x28) {
        int type = col[0];
        uint8_t *u2 = (uint8_t *)first_unit_or_type();
        (void)type; (void)u2;

        uint8_t *kr = (uint8_t *)g_king_record_84FC;
        if (*(int16_t *)(kr + 0x2c) > 0 ||
            (*(int16_t *)(kr + 0x2c) == 0 &&
             (uint16_t)*(int16_t *)(kr + 0x2a) >= 0xA)) {
            *(int16_t *)(kr + 0x2a) -= 0xA;
            *(int16_t *)(kr + 0x2c) -= 0;
            col = (uint8_t *)g_colony_buf_8542;
            *(int16_t *)(col + 0xaa) = 2;
        }
    }

    g_result_flag_035E = 0;

    (void)is_capital; (void)ncol_owned; (void)ring_n; (void)owner;
}

