int compute_terrain_yield(int ring_a, int ring_b, int *out, int flag)
{
    int yield        = 0;
    int era_flag     = 0;
    int furs_penalty = 0;
    uint16_t rtig_inner = 0;

    int good_id = (int)func_009974_logic_sz_18((uint16_t)ring_a, (uint16_t)ring_b, &rtig_inner);
    *out = good_id;
    if (good_id < 0) return 0;

    int col_x = (int)(uint8_t)ctx->map_x + ring_a - 2;
    int col_y = (int)(uint8_t)ctx->map_y + ring_b - 2;

    int feat_byte = ov_feature_flags_10E(col_x, col_y) & 0xFF;
    int terrain   = func_00624E_logic_sz_8((uint16_t)feat_byte);
    int resource  = ov_resource_at_4B0(col_x, col_y);

    yield = g_terrain_yield_table[terrain * 16 + good_id];

    if (yield != 0) {

        if (good_id >= 8) {
            int adj = count_adjacent_terrain(col_x, col_y, 0x19, 0x1A);

            if      (adj >= 8) yield -= 2;
            else if (adj >= 6) yield -= 1;
            else               yield += 1;
        }

        if (good_id == 4) {
            if (ov_feature_flags_142(col_x, col_y) & 0x0A) yield += 1;
        }

        if (feat_byte & 0x40) {
            yield += 1;
            if (feat_byte & 0x80) yield += 1;
        }
    }
    if (yield < 0) yield = 0;

    int match_idx = lookup_byte_from_pair(ring_a, ring_b);
    int field40   = current_unit_field_at_40(match_idx);
    int is_profmatch = (field40 == good_id) ? 1 : 0;
    int is_special   = (field40 == 0x1b)    ? 1 : 0;

    if (good_id == 0 || good_id == 8) era_flag = 1; else era_flag = 0;

    {
        int sol_pct  = sol_membership_pct();
        int tory_pct = 100 - sol_pct;
        int pop      = (int)(uint8_t)ctx->population;
        int tory_cnt = (pop * tory_pct + 0x32) / 100;
        int active   = (ctx->owner_power < 4 &&
                        g_power_records[ctx->owner_power][0] == 0);
        int divisor;
        if (active) {
            divisor = 0xA - (int)g_difficulty_53A6;
        } else {
            divisor = 0xA;
        }
        if (!active) tory_cnt = 0;
        int sol_adj = -(tory_cnt / divisor);
        if (ctx->flags_at_1c & 4) sol_adj += 1;
        if (ctx->flags_at_1c & 2) sol_adj += 1;

        if (yield != 0 && sol_adj > 0)
            yield += sol_adj;

        if (is_profmatch && yield != 0) {
            if (era_flag != 0) {
                yield += 2;
                if (sol_adj > 0) yield += sol_adj;
            } else {
                yield <<= 1;
            }
        }

        int rbonus = feature_yield_bonus(resource, good_id);
        if (resource == 7 && yield <= 0) rbonus = 0;
        if (rbonus < 0) {
            yield <<= 1;
        } else {
            if (is_profmatch) rbonus <<= 1;
            yield += rbonus;
        }

        if (resource == 6) {
            if (good_id == 6) g_table_A896 += 1;
            if (good_id == 7) g_table_A896 += 2;
        }
        if (resource == 0xC && good_id == 7) g_table_A896 += 1;
        if (good_id == 7 && resource == -1) {
            if ((ov_feature_flags_142(col_x, col_y) & 4) == 0)
                furs_penalty = 1;
            if (good_id == 7) {
                if ((ov_feature_flags_142(col_x, col_y) & 4) == 0 && yield != 0) {

                    if ((ov_feature_flags_142(col_x, col_y) & 0x0A) || is_profmatch)
                        yield = 1;
                    else
                        yield = 0;
                }
            }
        }
        if (good_id == 5) yield <<= 1;

        if (yield > 0 && furs_penalty == 0) {
            int tier = 1;

            if ((!is_profmatch && good_id == 5) ||
                ( is_profmatch && era_flag == 0) ||
                ( is_profmatch && good_id == 5))
                tier = 2;
            int add = 0;
            if (good_id == 0) add = tier;
            if ((ov_feature_flags_142(col_x, col_y) & 0x0A) && good_id > 3)
                add += tier;
            if ((ov_feature_flags_142(col_x, col_y) & 0x40) && good_id <= 3)
                add += tier;
            if (feat_byte & 0x40) {
                add += tier;
                if ((feat_byte & 0x80) && add == tier)
                    add += tier;
            }
            yield += add;
        }

        if (good_id >= 8) {
            if (test_building_or_father_bit(6) == 0)
                yield = 0;
        }
        if (good_id == 4) {
            if (ov_power_flag(ctx->owner_power, 8))
                yield <<= 1;
        }

        if (is_special && yield > 0) {

            if (good_id == 0 || good_id == 2 || good_id == 3 ||
                good_id == 1 || good_id == 4 || good_id >= 8)
                yield += 1;
        }

        if (yield < 0) yield = 0;
        if (flag != 0 && good_id >= 8) *out = 0;
        if (yield != 0 && sol_adj < 0) {
            yield += sol_adj;
            if (yield < 0) yield = 0;
        }
    }
    return yield;
}

void colony_turn_update(void)
{

    g_table_A895 = 0;
    g_table_A896 = 0;

    int terrain = func_00627A_op_sz_57((uint16_t)ctx->map_x, (uint16_t)ctx->map_y);

    if (terrain == 0x18) {
        g_table_A891 = 0;
    } else if (terrain == 1 || terrain == 0x11 || terrain == 9) {
        g_table_A891 = 1;
    } else if (terrain == 0x1B || terrain == 0x1C ||
               (terrain >= 8 && terrain < 0x10) ||
               (terrain >= 0x10 && terrain < 0x18)) {
        g_table_A891 = 2;
    } else {
        g_table_A891 = 3;
    }

    if (g_difficulty_53A6 == 0) g_table_A891 += 2;
    if (g_difficulty_53A6 == 1) g_table_A891 += 1;

    if (ov_feature_flags_142(ctx->map_x, ctx->map_y) & 0x40)
        g_table_A891 += 1;

    int center_resource = ov_resource_at_4B0(ctx->map_x, ctx->map_y);
    int center_feat     = ov_feature_flags_10E(ctx->map_x, ctx->map_y) & 0xFF;
    int feature_tier = 0;
    if (center_feat & 0x40) {
        feature_tier = 1;
        if (center_feat & 0x80) feature_tier = 2;
    }

    if (center_resource == 1 || center_resource == 9 || center_resource == 2)
        g_table_A891 += 2;

    if (ctx->flags_at_1c & 4) g_table_A891 += 1;
    if (ctx->flags_at_1c & 2) g_table_A891 += 1;

    g_table_A893 = (int8_t)0xFF;
    g_table_A894 = 0;
    {
        int commodity;
        for (commodity = 1; commodity < 8; commodity++) {
            if (commodity == 5) continue;

            int base = g_terrain_yield_table[terrain * 16 + commodity];
            int modifier = feature_yield_bonus(center_resource, commodity);
            int y;
            if (modifier >= 0) y = base;
            else               y = base * 2;
            y += modifier;
            if ((int)(uint8_t)g_table_A894 < y) {
                g_table_A893 = (int8_t)commodity;
                g_table_A894 = (uint8_t)y;
            }
        }
    }

    if ((int8_t)g_table_A893 >= 0) {
        if (g_difficulty_53A6 == 0) g_table_A894 += 1;
        g_table_A894 += (uint8_t)feature_tier;
        if (ctx->flags_at_1c & 4) g_table_A894 += 1;
        if (ctx->flags_at_1c & 2) g_table_A894 += 1;
    }

    {
        int i;
        for (i = 0; i < 0x14; i++) {
            g_global_amount[i] = 0;
        }
    }

    g_global_amount[COMMODITY_FOOD] += (uint8_t)g_table_A891;

    if ((int8_t)g_table_A893 >= 0) {
        g_global_amount[(uint8_t)g_table_A893] += (uint8_t)g_table_A894;
    }

    {
        int ring_x, ring_y;
        for (ring_x = 0; ring_x < 5; ring_x++) {
            for (ring_y = 0; ring_y < 5; ring_y++) {
                int good_id;
                int yield = compute_terrain_yield(ring_y, ring_x, &good_id, 1);
                if (good_id < 0) continue;

                int match = lookup_byte_from_pair(ring_y, ring_x);
                if (ctx->job_at_20[match] == 8) {
                    g_table_A895 += (uint8_t)yield;
                }
                g_global_amount[good_id] += yield;
            }
        }
    }

    {
        int i;
        for (i = 0; i < (int)(uint8_t)ctx->population; i++) {
            int meta;
            int unit_yield = unit_individual_handler_9FFC(i, &meta);
            if (meta >= 0) {
                g_global_amount[meta] += unit_yield;
            }
        }
    }

    g_8DEA++;
    if (test_building_or_father_bit(0x25)) g_8DEA++;
    if (test_building_or_father_bit(0x26)) g_8DEA++;
    g_table_A892 = 0;
    g_8DEC++;

    if (ov_power_flag(ctx->owner_power, 0x0F)) {
        g_8DEC += g_8DEC >> 1;
    }

    if (ov_power_flag(ctx->owner_power, 0x11)) {
        int pct = (int)(uint8_t)g_power_byte_8809[ctx->owner_power * 0x13C];
        uint16_t prod = (uint16_t)(pct * (int)g_8DEC);
        g_8DEC += prod / 100;
    }

    if (ov_power_flag(ctx->owner_power, 0x12)) {
        int active = (ctx->owner_power < 4 &&
                      g_power_records[ctx->owner_power][0] == 0);
        if (!active) {
            g_8DEC += ((int)(uint8_t)ctx->population + 3) / 5;
        }
    }
    g_8DEC += (uint8_t)g_table_A892;

    if (test_building_or_father_bit(0x14)) {
        g_8DEC <<= 1;
    } else if (test_building_or_father_bit(0x13)) {
        g_8DEC += g_8DEC >> 1;
    }

    int quota_raw = 0;
    int quota_capped = 0;
    if (ctx->liberty_aa >= 2) {
        int divisor = test_building_or_father_bit(0x11) ? 0x19 : 0x32;
        quota_raw = (((int)ctx->liberty_aa + divisor - 1) / divisor) * 2;
    }
    quota_capped = quota_raw;

    int pop2 = (int)(uint8_t)ctx->population * 2;
    int food_surplus = (int)g_global_amount[COMMODITY_FOOD] - pop2;
    if (food_surplus < 0) food_surplus = 0;
    {
        int half = (food_surplus + 1) >> 1;
        if (half <= quota_raw) quota_capped = half;
    }

    int turn_step = step_100_or_level_scaled();
    int pressure = turn_step - (int)ctx->liberty_aa;
    if (pressure < 0) pressure = 0;
    if (pressure > quota_capped) pressure = quota_capped;

    g_8DD8 += (uint16_t)quota_raw;
    g_8E6A = (uint16_t)(quota_raw - pressure);
    int food_band = pop2 + pressure;

    dispatch_via_8e02_with_band(COMMODITY_FOOD,   (uint16_t)food_band);
    dispatch_via_8e02_with_band(COMMODITY_LUMBER, g_8DE8);
    update_finished_good_from_raw(COMMODITY_ORE,     COMMODITY_TOOLS);
    update_finished_good_from_raw(COMMODITY_TOBACCO, COMMODITY_CIGARS);
    update_finished_good_from_raw(COMMODITY_COTTON,  COMMODITY_CLOTH);
    update_finished_good_from_raw(COMMODITY_FURS,    COMMODITY_COATS);
    update_finished_good_from_raw(COMMODITY_SUGAR,   COMMODITY_RUM);
    dispatch_via_8e02_with_band(COMMODITY_TOOLS, g_8DE6);

}

void compute_colony_center_yields(void)
{
    colony_turn_update();
}

