void find_city_dialog(void)
{
    int found = -1;
    int count, idx;

    count = picker_run(KEY_FINDCITY + 1, KEY_FINDCITY, KEY_GAME, 0x17);
    if (count == 0)
        goto no_city;

    idx = count;

    while (found < 0) {
        if (idx >= (int)g_colony_count)
            break;
        ov_colony_select(idx);

        if (ov_colony_owned_visible((int)(g_active_colony_ptr + 2), 0x9820) == 0) {

            if ((int)g_active_player_idx < 4) {

                int owner = ov_colony_at_xy(g_active_colony_ptr[0],
                                            g_active_colony_ptr[1]);
                int mask  = 0x10 << (int)g_active_player_idx;
                if (!(mask & owner) && g_reveal_53A2 == 0)
                    goto next;
            }
            found = idx;
        }
    next:
        idx++;
    }

    if (found >= 0) {

        ov_open_colony(0, g_active_colony_ptr[0], g_active_colony_ptr[1]);

        return;
    }

no_city:

    ov_strbuf_init2(0, 0x9820, 0);
    ov_msg_show(KEY_NOCITY);

}

