void draw_box(int x1, int y1, int x2, int y2, int color)
{
    uint8_t *fb = vid_framebuffer();
    int xl = (x1 < x2) ? x1 : x2, xh = (x1 < x2) ? x2 : x1;
    int yl = (y1 < y2) ? y1 : y2, yh = (y1 < y2) ? y2 : y1;
    int lo, hi, p;
    lo = (xl < 0) ? 0 : xl;
    hi = (xh > VID_W - 1) ? VID_W - 1 : xh;
    for (p = lo; p <= hi; p++) {
        if (yl >= 0 && yl < VID_H) fb[yl * VID_W + p] = (uint8_t)color;
        if (yh >= 0 && yh < VID_H) fb[yh * VID_W + p] = (uint8_t)color;
    }
    lo = (yl < 0) ? 0 : yl;
    hi = (yh > VID_H - 1) ? VID_H - 1 : yh;
    for (p = lo; p <= hi; p++) {
        if (xl >= 0 && xl < VID_W) fb[p * VID_W + xl] = (uint8_t)color;
        if (xh >= 0 && xh < VID_W) fb[p * VID_W + xh] = (uint8_t)color;
    }
}
