void blit_sprite_solid(int id, int x, int y, int color)
{
    const ss_sheet_t *s = sheet_at(G_SHEET_ICONS);
    int idm = id & 0x7FFF;
    const ss_frame_t *f;
    uint8_t *fb;
    int r, c;
    if (!s || idm >= s->nframes) return;
    f  = &s->frames[idm];
    fb = vid_framebuffer();
    for (r = 0; r < (int)f->h; r++) {
        int py = y + r;
        if (py < 0 || py >= VID_H) continue;
        for (c = 0; c < (int)f->w; c++) {
            int px = x + c;
            if (px < 0 || px >= VID_W) continue;
            if (f->pixels[r * f->w + c] != SS_TRANSPARENT)
                fb[py * VID_W + px] = (uint8_t)color;
        }
    }
}

void blit_sprite_shadowed(int flags, int id, int x, int y)
{
    if (flags & 1)
        blit_sprite_solid(id, x, y, (flags & 4) ? 0x5F : 0);
    if (flags & 2)
        blit_sprite(0, id, x + 2, y);
}

void bar_queue_reset(void) { DG16(0x2CE0) = 0; }

void bar_queue_push(int id, int value, int tail)
{
    uint16_t i = DG16(0x2CE0);
    if (value == 0 && tail == 0) return;
    if (i >= 9) return;

    DG16(0x2CF4 + i*2) = (uint16_t)id;
    DG16(0x2CCE + i*2) = (uint16_t)value;
    DG16(0x2CE2 + i*2) = (uint16_t)tail;
    DG16(0x2CE0) = (uint16_t)(i + 1);
}

static void bar_count_badge(int value, int x, int y, int color, int boxed)
{
    char buf[0x16];
    ff_font_t *f = viceroy_font();
    int w;
    if (value <= 0 || !f) return;
    y += 2;
    snprintf(buf, sizeof buf, "%d", value);
    w = ff_text_width(f, buf, 1);
    if (boxed)
        vid_box_fill(x, y, w + 2, 7, 0);
    vid_text_color(color);
    vid_text_xy(buf, x + 1, y + 1);
}

static int icon_run_sizer(int flags, int16_t *out_shift, int16_t *out_rem,
                          int slot_w, int avail, int *x,
                          int spread, int total, int id)
{
    int base_w, rem_w, step, span, seg, top;
    if (spread == 0 || total == 0) return 0;
    *out_shift = 0;
    base_w = sheet_frame_w_icons(id);
    if (flags & 2) base_w += 2;
    rem_w = avail - base_w;
    if (total > 1) {
        step = rem_w / (total - 1);
        if (step > base_w + 1) step = base_w + 1;
        if (step < 1) step = 1;
    } else
        step = 1;
    span = (total - 1) * step;
    while ((span >> *out_shift) > rem_w && *out_shift < 15)
        (*out_shift)++;

    seg = (span >> *out_shift) + base_w;
    top = ((slot_w - 1 > seg) ? slot_w : avail) - seg;
    if (out_rem) *out_rem = (int16_t)top;
    if (slot_w != 0) *x += top >> 1;
    return step;
}

void draw_icon_run(int flags, int filled, int slot_w, int avail,
                   int y, int x, int id, int spread, int total)
{
    int16_t shift = 0, rem = 0;
    int last_full = 0;
    int step, acc, fill, fill_badge, fill_sh, inner, nrows, start_x, j, show;

    step = icon_run_sizer(flags, &shift, &rem, slot_w, avail, &x,
                          spread, total, id);
    if (step == 0) return;
    acc        = 0;
    fill       = total - filled;
    fill_badge = fill;
    fill_sh    = fill >> shift;
    inner      = spread >> shift;
    nrows      = total >> shift;
    if (shift != 0 && (filled & fill_badge & 1))
        fill_badge++;
    start_x    = x;
    for (j = 0; j < nrows; j++) {
        if (flags & 2)
            blit_sprite_shadowed(3, id, x, y + 1);
        else
            blit_sprite(0, id, x, y + 1);
        if (fill_sh == j) last_full = x;
        if (fill_sh <= j)
            blit_sprite(0, 0x38, x, y + 1);
        x += step;
        if (flags & 1) {
            acc += rem;
            while (acc >= inner && inner > 0) {
                acc -= inner; x++;
            }
        }
    }
    show = (int16_t)DG16(0x0070);
    if (step == 1 && total > 1) show = 1;
    if (show) {
        bar_count_badge(fill_badge, start_x + 2, y, 0xF, 1);
        bar_count_badge(filled, last_full + 2, y, 0xC, 1);
    }
}

void bar_row_flush(int x, int y, int x_limit, int spacing)
{
    int n = (int16_t)DG16(0x2CE0);
    int n_multi = 0, extra = 0;
    int wsum = 0, squeeze = 0;
    int avail = 0, scale = 0, shift = 0;
    int i, j;

    for (i = 0; i < n; i++) {
        int v = (int16_t)DG16(0x2CCE + i*2);
        if (v > 1) { n_multi++; extra += v - 1; }
    }
    for (i = 0; i < n; i++)
        wsum += sheet_frame_w_icons((int16_t)DG16(0x2CF4 + i*2) & 0xFFF);
    for (;;) {
        int cx = wsum - n * squeeze;
        if (cx < 0) cx = 0;
        avail = (1 - n) * spacing - cx + x_limit;
        if (avail < n_multi) {
            if (spacing > 0)      spacing--;
            else if (cx > 0)      squeeze++;
            else                  avail = n_multi;
        }
        if (n_multi <= avail) break;
    }
    if (extra != 0) {
        scale = avail / extra;
        if (scale == 0)
            do { shift++; } while ((extra >> shift) > avail && shift < 15);

    }
    for (i = 0; i < n; i++) {
        int id_full = (int16_t)DG16(0x2CF4 + i*2);
        int id      = id_full & 0xFFF;
        int value   = (int16_t)DG16(0x2CCE + i*2);
        int tail    = (int16_t)DG16(0x2CE2 + i*2);
        int lead    = value - tail;
        int lead_sh = lead >> shift;
        int label_x = x;
        int mark_x  = -1;
        int step, show;
        if (scale == 0)
            step = 1;
        else {
            step = sheet_frame_w_icons(id) + 1;
            if (step > scale) step = scale;
        }
        for (j = 0; j < (value >> shift); j++) {
            int hollow = (id_full & 0x4000) && j < lead_sh;
            if (j == lead_sh) mark_x = x;
            blit_sprite(0, hollow ? 0x3A : id, x, y);

            if (!hollow &&
                ((id_full & 0x8000) ||
                 (j >= lead_sh && !(id_full & 0x4000))))
                blit_sprite(0, 0x38, x, y);
            if ((value >> shift) - 1 > j)
                x += step;
        }
        show = (int16_t)DG16(0x0070);
        if (step == 1 && value > 1) show = 1;
        if (show) {
            int lead2 = lead, tval = tail;
            if (id_full & 0x4000) { lead2 += tail; tval = 0; }
            bar_count_badge(lead2, label_x + 2, y,
                            (id_full & 0x8000) ? 0xC : 0xF, 1);
            bar_count_badge(tval, mark_x + 2, y,
                            (id_full & 0x4000) ? 0xF : 0xC, 1);
        }
        x += sheet_frame_w_icons(id) - squeeze + spacing;
    }
}

enum { TEX_PARCH = 0, TEX_WOODTILE = 1, TEX_COUNT = 2 };
static ss_sheet_t g_tex[TEX_COUNT];
static int        g_tex_state[TEX_COUNT];
static const char *const g_tex_file[TEX_COUNT] = { "/PARCH.SS", "/WOODTILE.SS" };

static const ss_sheet_t *tex_ready(int which)
{
    if (which < 0 || which >= TEX_COUNT) return 0;
    if (g_tex_state[which] == 0) {
        char path[512];
        extern const char *viceroy_data_dir(void);
        const char *dir = viceroy_data_dir();
        size_t n = strlen(dir);
        if (n > sizeof path - 16) n = sizeof path - 16;
        memcpy(path, dir, n);
        strcpy(path + n, g_tex_file[which]);
        g_tex_state[which] = (ss_load(path, &g_tex[which]) == 0 &&
                              g_tex[which].nframes > 0) ? 1 : -1;
    }
    return g_tex_state[which] == 1 ? &g_tex[which] : 0;
}

void tile_texture(int which, int x, int y, int w, int h)
{
    const ss_sheet_t *s = tex_ready(which);
    if (!s) { return; }
    const ss_frame_t *f = &s->frames[0];
    int tw = (int)f->w, th = (int)f->h;
    if (tw <= 0 || th <= 0) return;
    uint8_t *fb = vid_framebuffer();
    for (int r = 0; r < h; r++) {
        int sy = y + r;
        if (sy < 0 || sy >= VID_H) continue;
        const uint8_t *srow = f->pixels + ((sy % th) * tw);
        uint8_t *drow = fb + sy * VID_W;
        for (int c = 0; c < w; c++) {
            int sx = x + c;
            if (sx < 0 || sx >= VID_W) continue;
            drow[sx] = srow[sx % tw];
        }
    }
}

void texture_fill_rect(int x, int y, int w, int h, int color)
{
    if (tex_ready(TEX_WOODTILE)) tile_texture(TEX_WOODTILE, x, y, w, h);
    else                         vid_box_fill(x, y, w, h, (uint8_t)color);
}

extern int classify_terrain(uint8_t raw);
extern int terrain_cell_transform_pub(int code);
int terrain_cell_transform_pub(int code) { return terrain_cell_transform(code); }

static int workgrid_terrain_frame(int wx, int wy)
{
    uint8_t raw = viceroy_layer_byte(0, wx, wy);
    int vis = classify_terrain(raw);
    int land_base;
    if (vis == 0x19 || vis == 0x1A)
        return terrain_cell_transform(vis);
    land_base = (vis < 0x18) ? (vis & 7) : vis;
    return terrain_cell_transform(land_base);
}

static void blit_terrain_scaled(const ss_sheet_t *s, int frame,
                                int dx, int dy, int dst_w, int dst_h)
{
    if (!s || frame < 0 || frame >= s->nframes) return;
    const ss_frame_t *f = &s->frames[frame];
    int sw = (int)f->w, sh = (int)f->h;
    if (sw <= 0 || sh <= 0) return;
    uint8_t *fb = vid_framebuffer();
    for (int r = 0; r < dst_h; r++) {
        int yy = dy + r;
        if (yy < 0 || yy >= VID_H) continue;
        int sy = r * sh / dst_h;
        const uint8_t *srow = f->pixels + sy * sw;
        uint8_t *drow = fb + yy * VID_W;
        for (int c = 0; c < dst_w; c++) {
            int xx = dx + c;
            if (xx < 0 || xx >= VID_W) continue;
            uint8_t p = srow[c * sw / dst_w];
            if (p != SS_TRANSPARENT) drow[xx] = p;
        }
    }
}

void colony_render_workgrid_terrain(void)
{
    int rec = (int16_t)DG16(g_current_colony_ptr);
    int cx  = (uint8_t)DG8(rec + 0);
    int cy  = (uint8_t)DG8(rec + 1);
    const ss_sheet_t *terr  = sheet_at(G_SHEET_TERRAIN);
    const ss_sheet_t *icons = sheet_at(G_SHEET_ICONS);
    int col, r, worker = 0;
    if (!terr) return;
    for (r = 1; r <= 3; r++) {
        for (col = 1; col <= 3; col++) {
            int cell_x = col * 0x18 + 0xC8;
            int cell_y = r   * 0x18 + 8;
            int wx = cx + col - 2;
            int wy = cy + r - 2;
            int frame = workgrid_terrain_frame(wx, wy);
            uint8_t raw = viceroy_layer_byte(0, wx, wy);
            int vis = classify_terrain(raw);
            int is_water = (vis == 0x19 || vis == 0x1A);
            int is_centre = (col == 2 && r == 2);
            blit_terrain_scaled(terr, frame, cell_x, cell_y, 0x18, 0x18);

            if (icons) {
                if (is_centre) {

                    ss_blit(icons, 0x52, cell_x + 5, cell_y + 5);
                } else if (!is_water) {

                    int prof = (int)DG8(rec + 0x40 + (worker & 7));
                    int amt  = 3 + (worker % 3);
                    char q[8];
                    ss_blit(icons, 0x52 + (prof & 7), cell_x + 2, cell_y + 8);

                    ss_blit(icons, 0x16, cell_x + 1, cell_y + 1);
                    snprintf(q, sizeof q, "%d", amt);
                    vid_text_color(0x0F);
                    vid_text_xy(q, cell_x + 14, cell_y + 1);
                    worker++;
                }
            }
        }
    }

    draw_box(0xC7, 7, 0x13F, 0x80, 0);
    draw_box(0xDF, 0x1F, 0x128, 0x68, 0);
}

void     *g_map_layer[4];
uint32_t  g_map_layer_bytes;
void viceroy_save_bind_layers(void)
{
    g_map_layer[0] = (void *)g_layer[0];
    g_map_layer[1] = (void *)g_layer[1];
    g_map_layer[2] = (void *)g_layer[2];
    g_map_layer[3] = (void *)g_layer[3];
    g_map_layer_bytes = (uint32_t)g_layer_len;
}

static uint8_t g_terrain_work[64*80];

void viceroy_map_load_bind(uint32_t bytes)
{
    if (bytes > sizeof g_feature_work) bytes = (uint32_t)sizeof g_feature_work;
    g_layer_len  = (long)bytes;
    g_layer[0]   = g_terrain_work;
    g_layer[1]   = g_feature_work;
    g_layer[2]   = g_resfog_work;
    g_layer[3]   = g_region_layer;
    g_map_layer[0] = g_terrain_work;
    g_map_layer[1] = g_feature_work;
    g_map_layer[2] = g_resfog_work;
    g_map_layer[3] = g_region_layer;
    g_map_layer_bytes = bytes;
    {   extern uint8_t *g_layer0_terrain, *g_layer1_elev,
                       *g_layer2_region, *g_layer3_mask;
        g_layer0_terrain = g_terrain_work;
        g_layer1_elev    = g_feature_work;
        g_layer2_region  = g_resfog_work;
        g_layer3_mask    = g_region_layer;
    }
}

