int colony_service_menu(int colony_sel, int item_id)
{
    int  attrs;
    int  field;
    int  sel;
    int  result;
    int  reshow = 1;
    uint8_t *col = colony_8542();
    (void)col;

    field = mn_colony_field(colony_sel);
    attrs = mn_colony_attr(colony_sel);
    sel   = item_id;
    if (sel == 0x17)
        sel = 0x15;

    result = mn_service_query(sel, colony_sel);

    switch (result) {
    case 21:
        mn_msg_popup(5, K_KEEPSTOCKADE);
        break;
    case 22:
        mn_msg_popup(5, K_MORETHANTHREE);
        break;
    case 2:
        mn_opt_register(K_ONE_ENTER);
        break;
    case 1:
        mn_opt_register(K_ONE_LEAVE);
        break;
    case 4:

        mn_msg_popup(5, K_FULL);
        break;
    case 3:

        break;
    case 7:  mn_msg_popup(5, K_UNIV3);    break;
    case 8:  mn_msg_popup(5, K_COLLEGE2); break;
    case 9:  mn_msg_popup(5, K_SCHOOL1);  break;
    case 16: mn_msg_popup(5, K_NOTEACHER);break;
    case 12: mn_msg_popup(5, K_ASSEMBLY); break;
    case 11: mn_msg_popup(5, K_TOWNHALL); break;
    case 10: mn_msg_popup(5, K_MEETINGHALL);break;
    case 13: mn_msg_popup(0, K_NODOCKS);  break;
    case 20: mn_msg_popup(1, K_SIEGE);    break;
    case 6: case 14: case 15:

        break;
    case 17:

        mn_msg_popup(5, K_NEEDCOLLEGE);
        break;
    case 18:

        mn_msg_popup(5, K_NEEDUNIVERSITY);
        break;
    case 5:

        break;
    case 19:
    default:

        break;
    }

    reshow = 0;

    return reshow;
}

