void colony_dialog_engine(int in_subview)
{

    int  force_wide = 0;
    int  reopen     = 0;
    int  edit_mode  = 0;
    int  list_n;
    int  row;
    int  cur_item;
    int  top_row;
    int  visible;
    uint8_t *col = colony_8542();

    (void)edit_mode; (void)reopen;

    if (!((int)(signed char)col[0x1F] > DG16(CD_LIST_CURSOR))
        && (col[0x1F] & 0xFF) >= 0x20) {
        in_subview = 1;
        force_wide = 1;
    }

    {
        int gate = 1;
        if (cd_list_first_ok(cd_colony_attr(DG16(CD_LIST_CURSOR))) == 0)
            gate = 0;
        (void)gate;
    }

    DG16(0x0334) = 0;
    cd_snapshot();

    if (in_subview != 0) {
        top_row = 0x13;  visible = 6;
    } else {
        top_row = 0;     visible = 0x19;
    }

    cur_item  = cd_colony_field(DG16(CD_LIST_CURSOR));
    edit_mode = (cur_item == 0x12) ? 1 : 0;

    list_n = cd_list_count(0);
    for (row = 0; row < list_n; row++) {

    }

    {
        void *win = cd_win_create(0x800, DG16(0x08A0), DG16(0x089E));
        if (win == 0)
            goto teardown;

        (void)win;
    }

teardown:

    DG16(CD_LISTACTIVE) = 0;
    cd_teardown();

}

