void ff_bells_tick(int power, int bells)
{
    unsigned p;

    ff_announce(power);
    p = DG16(g_current_power_ptr);
    DGS16(p + 0x0C) = (int16_t)(DGS16(p + 0x0C) + bells);
    DGS16(p + 0x0E) = (int16_t)(DGS16(p + 0x0E) + bells);

    if (!(DG8(g_game_phase_flags) & 0x01) &&
        DGS16(p + 0x12) < 0) {
        ff_become_available(power);
    }

    if ((DG8(g_game_phase_flags) & 0x01) &&
        !(DG8(g_game_phase_flags) & 0x06) &&
        DGS16(p + 0x0C) > bells) {
        cong_anim((int)DGS16(0x53D4), 1, 0);
        {
            long req = (long)ff_bells_required(power);
            ff_notify_sound(req, 0);
        }
        ui_key_print(0x126F , 1);
        ui_key_print(0x127A , 1);
        DG8(g_game_phase_flags) |= 0x04;
    }

    if (ff_bells_required(power) <= DGS16(p + 0x0C)) {
        if (DG8(g_game_phase_flags) & 0x01) {
            if (!(DG8(g_game_phase_flags) & 0x02))
                cong_screen_a();
        } else if (DGS16(p + 0x12) >= 0) {
            ff_log_notify(0, (int)DGS16(p + 0x12), power);
        }
        p = DG16(g_current_power_ptr);
        DGS16(p + 0x0C) = 0;
    }

}

void ff_congress_screen(int power)
{
    int16_t chosen[5];
    int cat, ff;
    int pick;
    int sum, budget;
    int band;
    int n_categories = 0;
    void *dlg = 0;
    int chosen_idx = 0;
    int sel;

    ff_announce(power);
    band = ff_category_band(power);

    for (cat = 0; cat < 5; cat++) {
        chosen[cat] = (int16_t)0xFFFF;
        sum = 0;
        if (ff_cat_candidate(cat, power) == 0)
            continue;
        n_categories++;

        for (ff = 0; ff < 25; ff++) {
            if (ff_owned(ff, power))
                continue;
            if (DG8(FF_MEM_BASE + (unsigned)ff * 6 + 0x02) != (uint8_t)cat)
                continue;
            sum += (int)DG8(FF_MEM_BASE + (unsigned)ff * 6 + 0x03 + (unsigned)band);
        }

        budget = random_int(1, sum);
        pick = -1;
        for (ff = 0; ff < 25 && pick < 0; ff++) {
            if (ff_owned(ff, power))
                continue;
            if (DG8(FF_MEM_BASE + (unsigned)ff * 6 + 0x02) != (uint8_t)cat)
                continue;
            budget -= (int)DG8(FF_MEM_BASE + (unsigned)ff * 6 + 0x03 + (unsigned)band);
            if (budget <= 0)
                pick = ff;
        }
        chosen[cat] = (int16_t)pick;
    }

    sel = ff_present_primer(power);

    if (power >= 4 ||
        DG8(AI_CTRL_543F + (unsigned)power * 0x34) != 0) {

        if (sel >= 0 && sel < 5) {
            unsigned p = DG16(g_current_power_ptr);
            DGS16(p + 0x12) = chosen[sel];
        }
        goto resolve_pending;
    }

    if (n_categories == 0)
        goto resolve_pending;

    ff_msg_open(3);

reopen_dialog:
    dlg = dlg_open((void *)0x087C ,
                   (void *)0x1262 , 0);
    if (dlg == 0)
        goto resolve_pending;
    *(int16_t *)((uint8_t *)dlg + 0x22) = 8;

    if (n_categories != 0) {
        char rowbuf[0x52];
        for (cat = 0; cat < 5; cat++) {
            if (ff_cat_candidate(cat, power) == 0)
                continue;
            rowbuf[0] = 0;

            {
                extern void ovly_text_applabel_16E(uint16_t labelptr, char *buf);
                extern void ovly_text_appsep_178(char *buf);
                int ffsel = chosen[cat];
                ovly_text_applabel_16E(DG16(FF_MEM_BASE + (unsigned)ffsel * 6), rowbuf);
                ovly_text_appsep_178(rowbuf);
                ovly_text_appsep_178(rowbuf);
                ovly_text_applabel_16E(DG16(FF_MEM2_BASE + (unsigned)cat * 2), rowbuf);
                ovly_text_appsep_178(rowbuf);
                ovly_text_applabel_16E(DG16(0x2E88), rowbuf);

            }
            dlg_add_row(dlg, rowbuf, cat + 1);
        }
    }

    DG16(0x1F66) = 1;
    chosen_idx = dlg_run(dlg);
    dlg_free(dlg);
    dlg = 0;

    if (chosen_idx <= 0) {
        extern int viceroy_interactive(void);
        if (viceroy_interactive())
            goto reopen_dialog;

        goto resolve_pending;
    }
    sel = chosen_idx - 1;
    if (DG16(0x1F68) != 0) {
        ff_pre_b((int)chosen[sel]);
        ff_animate_pre();
        goto reopen_dialog;
    }
    {
        unsigned p = DG16(g_current_power_ptr);
        DGS16(p + 0x12) = chosen[sel];
    }

resolve_pending:

    if (dlg != 0)
        dlg_free(dlg);

    (void)band;
}

