void king_process_power_events(void)
{
    int  P     = g_subject_power_5394;
    int  i;
    int  found_idx;

    ovly_181F_0590(g_class_table_0848[P]);

    g_found_flag_014C  = 0;
    g_found_value_014E = (int16_t)0xFFFF;

    for (i = g_unit_count_539C - 1; i >= 0; i--) {
        uint8_t *u = (uint8_t *)DGROUP_PTR(UNIT_BASE_3144 + i * UNIT_STRIDE);

        if ((u[U_OWNFLG_3147 - UNIT_BASE_3144] & 0x0F) != P)
            continue;

        unit_select(i);
        if (unit_class_check(i) == 0)
            continue;

        {
            int type = u[U_TYPE_3146 - UNIT_BASE_3144];
            if (type < 0x0D) {
                continue;
            }
            if (type > 0x12) {
                continue;
            }

        }

        u[U_REFIT_315A - UNIT_BASE_3144]++;
        if (is_xy_in_map_bounds(u[U_XPOS_3144 - UNIT_BASE_3144],
                                u[U_YPOS_3145 - UNIT_BASE_3144]) != 0)
            u[U_REFIT_315A - UNIT_BASE_3144]++;

        {
            int type     = u[U_TYPE_3146 - UNIT_BASE_3144];
            int progress = u[U_REFIT_315A - UNIT_BASE_3144];
            int duration = ((uint8_t *)DGROUP_PTR(UNIT_REFIT_TABLE_5235))[type * UNIT_TYPE_STRIDE_7];
            if (duration - progress > 0)
                continue;
        }

        u[U_FLAGS_3148 - UNIT_BASE_3144] &= 0x7F;
        if (P >= 4) continue;
        if (((uint8_t *)DGROUP_PTR(AI_CTRL_543F))[P * POWER_STRIDE_34] != 0)
            continue;

        {
            int type = u[U_TYPE_3146 - UNIT_BASE_3144];
            ui_select_on_map(((uint16_t *)DGROUP_PTR(UNIT_TYPE_WORD_5230))[type * UNIT_TYPE_STRIDE_7 / 2],
                             0);

            if (unit_class_check2(u[U_XPOS_3144 - UNIT_BASE_3144],
                                  u[U_YPOS_3145 - UNIT_BASE_3144]) != 0) {
                int slot = find_landing_slot(u[U_XPOS_3144 - UNIT_BASE_3144],
                                             u[U_YPOS_3145 - UNIT_BASE_3144]);
                if (slot >= 0) {
                    void *colrec = DGROUP_PTR(g_colony_table__name[0] + slot * 0xCA);
                    msg_set_ptr(1, colrec, 0);
                } else {

                    msg_set_int(1, ((uint16_t *)DGROUP_PTR(0x838C))[P]);
                }
            }
            ui_set_channel(0x54);
            ui_show_message(0, MSG_REFIT);

            if (unit_class_check(i) != 0) continue;
            g_found_flag_014C = 1;
            continue;
        }
    }

    ui_redraw_power(P);
    ui_redraw_power(P);
    ui_flush();
    if (g_found_flag_014C != 0)
        ovly_181F_05FA(P, g_found_value_014E);
    ((int16_t *)g_king_record_84FC)[0x0E / 2] = 0;

    for (i = g_colony_count_539E - 1; i >= 0; i--) {
        uint8_t *col_owner = (uint8_t *)DGROUP_PTR(COL_OWNER_5D60 + i * 0xCA);
        if (*col_owner == (uint8_t)P)
            ui_refresh_colony(i);
    }
    ui_redraw_power(P);
    ui_redraw_power(P);

    if (!(*(uint8_t *)DGROUP_PTR(0xA89B) != 0 ||
          *(uint8_t *)DGROUP_PTR(0xA89A) > 3))
        return;

    if (((uint8_t *)DGROUP_PTR(0x9258))[P * 0x13] != 0)
        return;

    if (*(uint8_t *)DGROUP_PTR(g_game_phase_flags) & 1) return;
    if (*(uint8_t *)DGROUP_PTR(g_turn) & 7) return;

    int decision;
    if (P < 4 &&
        ((uint8_t *)DGROUP_PTR(AI_CTRL_543F))[P * POWER_STRIDE_34] == 0) {
        msg_set_int(0, ((uint16_t *)DGROUP_PTR(g_king_galleon_displaynum[diff]))[g_difficulty_53A6]);
        msg_set_ptr(1, DGROUP_PTR(g_ai_table + P * 0x34), 0);
        msg_set_int(2, power_label(P));
        ovly_181F_048E(0x3E);
        decision = msg_key_lookup(DGROUP_PTR(MSG_WINNING_KEY));
    } else {
        decision = 1;
    }

    if (decision != 1) return;

    found_idx = spawn_unit(0x11, P, P - 0x18, P - 0x18);
    if (found_idx < 0) return;
    {
        uint8_t *nu  = (uint8_t *)DGROUP_PTR(UNIT_BASE_3144 + found_idx * UNIT_STRIDE);
        uint8_t *kr  = (uint8_t *)g_king_record_84FC;
        nu[U_ORDERS_314C - UNIT_BASE_3144] = 0;
        nu[U_GOTOX_314D - UNIT_BASE_3144] = kr[0x32];
        nu[U_GOTOY_314E - UNIT_BASE_3144] = kr[0x33];
        nu[U_REFIT_315A - UNIT_BASE_3144] =
            (uint8_t)pick_grant_unit_type(kr[0x33], 0, found_idx);
        nu[U_FLAGS_3148 - UNIT_BASE_3144] |= 0x40;
    }

    if (P < 4 &&
        ((uint8_t *)DGROUP_PTR(AI_CTRL_543F))[P * POWER_STRIDE_34] == 0)
        overlay_call_191F_0AE0(0xf01, 0xa);

}

