int order_assign(int order_key)
{
    int code = 0;
    int u;

    if (order_key == 0x14) code = 2;
    if (order_key == 0x18) code = 3;
    if (order_key == 0x16) code = 5;
    if (order_key == 0x15) {
        int r;
        code = 1;

        if ((int)G16(0x9E12) < 4 &&
            G8(AI_CTRL_543F + (int)G16(0x9E12) * 0x34) == 0)
            r = G8(g_difficulty);
        else
            r = 1;
        if (random_int(0, r + 4) == 0)
            code = 4;
    }

    u = unit_select_for_order(code,
                              (int)G16(0x9E12),
                              (int)G16(0x9E12) - 0x14,
                              (int)G16(0x9E12) - 0x14);
    if (u >= 0) {
        UNIT(u)[0x08] = 1;
        UNIT(u)[0x17] = (unsigned char)order_key;
        if (code == 2)
            UNIT(u)[0x15] = 0x64;
    }
    return u;
}

