void bar_geometry(int grade, int base_x, int min_count, int step,
                  int *band, int *x, int *marker, int *w0, int *w1)
{
    int g = grade;
    int low = 0;
    int step_px;

    *band = 0;
    if (g < 4) {
        low = g;
    } else {
        (*band)++;
        g -= 4;
        while (g >= 8) { (*band)++; g -= 8; }
        low = g;
        (*band)++;
    }

    step_px = 0x10 >> *band;
    *w0 = step_px;
    *w1 = step_px;
    if (*band == 0) *w1 = step_px + step;
    if (*band == 2) (*w1)++;

    *x = low * (*w1) + base_x;

    if (*band == 0)      *marker = 0x92;
    else if (*band == 1) *marker = 0x89;
    else if (*band == 2) *marker = 0x84;
    (void)min_count;
}

void unit_cargo_row(int unit_idx, int x, int y, int w, int *state)
{
    int kind;
    int rx, rw;
    int type = UNIT(unit_idx)[0x02];
    (void)y; (void)w;

    cargo_row_decode();
    rx = 0; rw = 0; kind = 0;

    if (kind >= 2) goto tail;

    sprite_blit();

    if (type >= 0x0D && type <= 0x12 &&
        kind == 0 &&
         1 &&
        UNIT(unit_idx)[0x0C] != 0) {
        overlay_call_181F_0BE6(unit_idx, 0);
        box_fill();
    }

tail:

    if (kind < 3) {
        sprite_blit2();
    }

    if ( 1 && kind < 3) {
        hline();
    }
    (*state)++;
    (void)x; (void)rx; (void)rw;
}

