#define MSG_LOSENOCOLONIES 0xF09
#define MSG_WINNING        0xF18
#define MSG_KINGLOSE       0xF20
#define MSG_LOSING0        0xF29
#define MSG_KINGWIN        0xF31
#define MSG_WARN0          0xF39
#define MSG_INDEPENDENT    0xF3F
#define MSG_NAMES          0xF4B
#define MSG_OTHERGRANTED   0xF51
#define MSG_OTHERMIGHT     0xF5E
#define MSG_OTHERLESS      0xF69
#define MSG_SOONRETIRING   0xF73
#define MSG_RETIRING       0xF80
#define MSG_RETIRING2      0xF89
#define MSG_SCORED         0xF93

void king_war_turn(void)
{
    int  P = g_active_power_5398;
    int  show_summary = 1;
    int  i;

    if (g_flags_5382 & 1)
        ui_redraw_power(g_enemy_power_53D2);

    ui_redraw_power(P);
    ((uint8_t *)DGROUP_PTR(POWER_NCOL_9230))[P] = 0;
    for (i = 0; i < g_colony_count_539E; i++) {
        if (((uint8_t *)DGROUP_PTR(COL_OWNER_5D60))[i * COL_STRIDE_CA] == (uint8_t)P)
            ((uint8_t *)DGROUP_PTR(POWER_NCOL_9230))[P]++;
    }

    if (g_year_538A >= 0x640 &&
        ((uint8_t *)DGROUP_PTR(POWER_NCOL_9230))[P] == 0 &&
        !(g_flags_5382 & 1)) {
        msg_set_int(0, ((uint16_t *)DGROUP_PTR(DIFF_LABEL_8394))[g_difficulty_53A6]);
        msg_set_ptr(1, DGROUP_PTR(POWER_NAME_540E + P * POWER_STRIDE_34), 0);
        ui_show_message_h(MSG_LOSENOCOLONIES);
        if (!(g_flags_5382 & 0x10))
            ui_commit_message();
        g_score_result_53C2 = 0;
        show_summary = 0;
        goto finish;
    }

    if (g_flags_5382 & 1) goto war_tail;
    if (g_flags_5382 & 8) goto war_tail;

    if (((uint8_t *)DGROUP_PTR(POWER_NCOL_9230))[g_enemy_power_53D2] != 0 &&
        !(g_flags_5382 & 0x20))
        goto ref_landing;

    {
        int mil = 0;
        for (i = 0; i < g_unit_count_539C; i++) {
            uint8_t *u = (uint8_t *)DGROUP_PTR(UNIT_BASE_3144 + i * UNIT_STRIDE_1C);
            if ((u[U_OWNFLG_3147 - UNIT_BASE_3144] & 0x0F) != g_enemy_power_53D2)
                continue;
            int type = u[U_TYPE_3146 - UNIT_BASE_3144];
            if (type == 6 || type == 8 || type == 0xB)
                mil++;
        }

        int threshold = (g_flags_5382 & 0x40) ? 8 : 1;
        if (threshold > mil) {

            int ready = ((g_ref_artillery_53E0 >= 1) ? 1 : 0)
                      + ((g_ref_cavalry_53DC   >= 1) ? 1 : 0)
                      + g_ref_regulars_53DA;
            if (ready >= 4) {
                if (g_flags_5382 & 0x20) goto ref_landing;
            }
        } else {
            if (g_flags_5382 & 0x20) goto ref_landing;
        }

        msg_set_ptr(0, DGROUP_PTR(POWER_NAME_540E + P * POWER_STRIDE_34), 0);
        msg_set_ptr(1, DGROUP_PTR(POWER_REC_5426  + P * POWER_STRIDE_34), 0);
        ovly_181F_0182(3, 0, 0);
        crt_keyed_to_buf(MSG_WINNING, 0);
        ui_show_message_3(MSG_KINGLOSE, 2, 1);
        g_flags_5382 |= 8;
        g_some_flag_0104 = 1;
        goto finish;
    }

ref_landing:

    {
        int generals = 0;
        for (i = 0; i < g_colony_count_539E; i++) {
            unit_select(i);
            uint8_t *col = (uint8_t *)g_colony_base_8542;
            if (col[0x1A] == (uint8_t)P && (col[0x1C] & 0x40))
                generals++;
        }

        int a_lvl = (generals < 3) ? 1 : 0;
        int b_lvl = (generals == 0) ? 1 : 0;
        int g_friend = ((uint8_t *)DGROUP_PTR(POWER_FRIEND_9404))[g_enemy_power_53D2];
        if (g_friend == 0) g_friend = 2;
        int p_friend = ((uint8_t *)DGROUP_PTR(POWER_FRIEND_9404))[P];
        if (p_friend == 0) p_friend = 2;
        int pct = (g_friend * 100) / (p_friend + g_friend);
        if (pct >= 0x50) a_lvl = 3;
        if (pct >= 0x5A) b_lvl = 3;
        if (((uint8_t *)DGROUP_PTR(POWER_NCOL_9230))[P] < 3) a_lvl = 2;
        if (((uint8_t *)DGROUP_PTR(POWER_NCOL_9230))[P] == 0) b_lvl = 2;

        if (b_lvl != 0) {

            msg_set_ptr(0, DGROUP_PTR(POWER_REC_5426 + P * POWER_STRIDE_34), 0);
            msg_set_ptr(1, DGROUP_PTR(POWER_NAME_540E + P * POWER_STRIDE_34), 0);
            ui_show_message_3(MSG_LOSING0, 0, 2);
            crt_keyed_to_buf(MSG_LOSING0, 0);
            msg_set_int(0, ((uint16_t *)DGROUP_PTR(POWER_NAMEW_8D42))[P]);
            ui_show_message_3(MSG_WARN0, 1, 2);
            ui_show_message_0();
            goto warn_loop;
        }

        if (a_lvl == 0) goto war_tail;

        crt_keyed_to_buf(MSG_WARN0, 0);
        msg_set_ptr(0, DGROUP_PTR(POWER_REC_5426 + P * POWER_STRIDE_34), 0);
        msg_set_long(0, generals);
        msg_set_long(1, ((uint8_t *)DGROUP_PTR(POWER_NCOL_9230))[P]);
        msg_set_long(2, pct);
        ui_show_message(1, MSG_WARN0);

    }

warn_loop:
war_tail:

    if (g_flags_5382 & 1) {
        int arm;
        for (arm = 0; arm < 4; arm++) {
            if (arm < 4 && ((uint8_t *)DGROUP_PTR(AI_CTRL_543F))[arm * POWER_STRIDE_34] != 0)
                continue;
            ui_redraw_power(arm);
            uint8_t *kr = (uint8_t *)g_king_record_84FC;
            if (kr[0] & 4) continue;

            int needed = (kr[0x19] * ((uint8_t *)DGROUP_PTR(REF_ARM_TYPE_9408))[arm]) / 100;
            if (needed > 100) needed = 100;
            int target_val = needed;

            int budget = (8 - g_difficulty_53A6) * 10;

            if (target_val >= budget) {

                ui_flash_power(arm, 0, 0);
                msg_set_ptr(1, DGROUP_PTR(POWER_REC_5426 + arm * POWER_STRIDE_34), 0);
                msg_set_ptr(2, DGROUP_PTR(POWER_NAME_540E + arm * POWER_STRIDE_34), 0);

                ui_fmt_two(arm, MSG_INDEPENDENT, MSG_NAMES);
                crt_keyed_to_buf(MSG_OTHERGRANTED, 0);
                kr[0] |= 4;

            } else {

                if (budget - 20 <= needed &&
                    kr[0x1A] < (uint8_t)needed) {
                    ui_flash_power(arm, 0, 0);
                    msg_set_long(0, (int32_t)needed);
                    msg_set_long(1, (int32_t)((uint8_t *)DGROUP_PTR(REF_ARM_TYPE_9408))[arm]);
                    msg_set_long(2, (int32_t)budget);
                    msg_set_int(1, power_handle(arm));
                    ui_show_message(2, MSG_OTHERMIGHT);
                    kr[0x1A] = (uint8_t)needed;
                }
                if (kr[0x1A] - 5 > (uint8_t)needed) {
                    ui_flash_power(arm, 0, 0);
                    msg_set_long(0, (int32_t)needed);
                    msg_set_long(1, (int32_t)((uint8_t *)DGROUP_PTR(REF_ARM_TYPE_9408))[arm]);
                    msg_set_long(2, (int32_t)budget);
                    msg_set_int(1, power_handle(arm));
                    ui_show_message(2, MSG_OTHERLESS);
                    kr[0x1A] = (uint8_t)needed;
                }
            }
        }
    }

    if (g_flags_5382 & 0x10) goto finish;
    if (g_turn_in_year_538C != 0) goto finish;

    if ((g_year_538A == 0x6FE && !(g_flags_5382 & 1)) ||
        (g_year_538A == 0x730 && (g_flags_5382 & 1))) {
        msg_set_int(0, ((uint16_t *)DGROUP_PTR(DIFF_LABEL_8394))[g_difficulty_53A6]);
        msg_set_ptr(1, DGROUP_PTR(POWER_NAME_540E + P * POWER_STRIDE_34), 0);
        crt_keyed_to_buf(MSG_SOONRETIRING, 0);
        int late = (g_year_538A == 0x6FE) ? 0 : 1;
        ovly_181F_0182(late, 0, 0);
        ui_show_message(1, MSG_SOONRETIRING);
    }

    if ((g_year_538A == 0x708 && !(g_flags_5382 & 1)) ||
        (g_year_538A == 0x73A)) {
        int best_rank = 0;
        int best_col  = 0;
        for (i = 0; i < g_colony_count_539E; i++) {
            unit_select(i);
            uint8_t *col = (uint8_t *)g_colony_base_8542;
            if (col[0x1A] != (uint8_t)P) continue;
            if (col[0x1F] < (uint8_t)best_rank) continue;
            best_rank = col[0x1F];
            best_col  = i;
        }
        msg_set_int(1, ((uint16_t *)DGROUP_PTR(DIFF_LABEL_8394))[g_difficulty_53A6]);
        msg_set_ptr(1, DGROUP_PTR(POWER_NAME_540E + P * POWER_STRIDE_34), 0);
        msg_set_ptr(2, DGROUP_PTR(COL_RECORD_5D48 + best_col * COL_STRIDE_CA), 0);

        int retire_key = (g_flags_5382 & 1) ? MSG_RETIRING2 : MSG_RETIRING;
        crt_keyed_to_buf(retire_key, 0);
        ui_commit_message();
    }

finish:

    g_score_result_53C2 = 0;
    if (g_score_result_53C2 == 0 && show_summary != 0) {
        if (g_flags_5382 & 8)
            g_retire_flag_53A2 = 1;
        ui_show_message_0();
        int r = msg_key_lookup(DGROUP_PTR(MSG_SCORED));
        if (r == 2)
            g_score_result_53C2 = 1;
    }
    g_flags_5382 |= 0x10;

}

