void europe_draw_stockpile(int blit)
{
    char pstr[16];
    int  i, x = 1;

    vid_box_fill(0, 0xB3, 0x140, 0x15, 0);

    for (i = 0; i < 0x10; i++) {
        int sid   = i + 0x16;
        int hw    = sheet_frame_w_icons(sid) >> 1;
        int dx    = x - hw + 9;

        blit_sprite(0, sid, dx, 0xB5);

        snprintf(pstr, sizeof pstr, "%d", market_bid_price(i));
        vid_text_color(0x0F);
        vid_text_xy(pstr, x + 9 - (vid_text_width(pstr) >> 1), 0xC2);

        x += 0x13;
    }

    {
        char gstr[24];
        snprintf(gstr, sizeof gstr, "$%d", (int)(int16_t)DG16(0x2F5E));
        vid_text_color(0x0F);
        vid_text_xy(gstr, 0x132, 0xB3);
    }
    (void)blit;
}

void europe_draw_title(int blit)
{
    static const char *nations[4] = { "English", "French", "Spanish", "Dutch" };
    char hdr[96];
    int  power = (int)(int16_t)DG16(0x9E12);
    int  year  = (int)(int16_t)DG16(g_year);
    int  pr_lo = (int)(g_power_table + (unsigned)power * 0x13C);
    int  tax   = (int)DG8((uint16_t)(pr_lo + 0x01));
    int  tw;

    if (power < 0 || power > 3) power = 0;
    snprintf(hdr, sizeof hdr, "%s Port  %d  Tax %d%%",
             nations[power], year, tax);
    tw = vid_text_width(hdr);
    vid_text_color(ui_color_for(0x52, 0x8A, 0x31));
    vid_text_xy(hdr, (320 - tw) >> 1, 4);
    (void)blit;
}

void europe_draw_dock_ships(int blit)
{
    int i, sx;

    vid_box_fill(0x8F, 0x76, 0x51, 0x3C, 0);

    vid_box_fill(0x8F, 0x51, 0x78, 0x45, 0);

    sx = 0x8F;
    for (i = 0; i < 6; i++) {
        int hw = sheet_frame_w_icons(0x7B) >> 1;
        blit_sprite(0, 0x7B, sx + 10 - hw, 0x76 + 4);
        sx += 0x78 / 6;
    }
    (void)blit;
}

void europe_draw_recruit_pool(int blit)
{
    static const char *lbls[3] = { "RECRUIT", "PURCHASE", "TRAIN" };
    int  i, cy = 0x59;
    int  cell_h = (0x20 - 4) / 3;

    vid_box_fill(0x119, 0x59, 0x25, 0x20, 0);

    for (i = 0; i < 3; i++) {
        int tw;

        vid_box_outline(0x119, cy, 0x25, cell_h, 0x39);

        tw = vid_text_width(lbls[i]);
        vid_text_color(0x0F);
        vid_text_xy(lbls[i], 0x119 + (0x25 - tw) / 2, cy + 1);
        cy += cell_h + 2;
    }
    (void)blit;
}

void europe_screen_render(void)
{

    fill_rect(0, 8, 320, 192);
    ov_prep_clip();

    europe_draw_stockpile(0);

    europe_draw_title(0);

    europe_draw_dock_ships(0);

    ov_draw_extra_a(0);
    ov_draw_extra_b(0);

    europe_draw_recruit_pool(0);

    box_frame(0, 0, 320, 200, 0);
}

