#define KING_TAX_RATE_OFF   0x01
#define KING_BOYCOTT_MASK   0x20
#define KING_PRICE_BC       0xBC
#define TAX_CAP             0x4B

#define MARKET_PRICE_5DE0   MARKET_PRICE_5DE0
#define MARKET_BLOCK_STRIDE 0x65

extern int32_t crt_lmul(int32_t a, int32_t b);
extern int32_t crt_aFldiv(int32_t a, int32_t b);

void tax_apply_delta(int delta)
{
    uint8_t *king = (uint8_t *)g_king_record_84FC;

    if (delta < 0) {
        int8_t mag = (int8_t)(~(uint8_t)delta + 1);
        if (mag > (int8_t)king[KING_TAX_RATE_OFF]) {
            delta = -(int8_t)king[KING_TAX_RATE_OFF];
        }
    }

    king[KING_TAX_RATE_OFF] = (uint8_t)(king[KING_TAX_RATE_OFF] + (int8_t)delta);

    if ((int8_t)king[KING_TAX_RATE_OFF] > TAX_CAP) {
        int over = (int)king[KING_TAX_RATE_OFF] - TAX_CAP;
        king[KING_TAX_RATE_OFF] = (uint8_t)(king[KING_TAX_RATE_OFF] - over);
        delta -= over;
    }

    if (delta == 0) return;

    if (g_active_power_9E12 >= 4) return;
    if (g_ai_personality_543F[g_active_power_9E12 * 0x34] != 0) return;

}

