#define NUM_GOODS 16

extern int                 g_active_power_index;
typedef struct PowerRecord PowerRecord;

#define PR_PRICE_LEVEL(p,g)  (*((unsigned char *)(p) + 0x4C + (g)))
#define PR_VOL_ACCUM(p,g)    (*(short *)((char *)(p) + 0x5C + (g)*2))
#define PR_GOLD(p)           (*(int32_t *)((char *)(p) + 0x2A))

extern unsigned char g_cargo_param[NUM_GOODS * 9];
#define CARGO(g,field)  g_cargo_param[(g)*9 + (field)]

