void market_set_active(int power)
{
#ifdef _VICEROY_MODERN

    extern uint8_t g_dgroup[];
    DG16_AT(0x9E12) = (uint16_t)power;
    DG16_AT(g_current_power_ptr) = (uint16_t)(g_power_table + power * 0x13C);
    g_market = (PowerRecord *)(g_dgroup + g_power_table + power * 0x13C);
#else
    g_active_power_index = power;
    g_market = (PowerRecord *)(g_power_table + power * 0x13C);
#endif
}

void market_price_drift(int arg_mode, int good_filter)
{
    long supply[NUM_GOODS];
    long S_pair;
    long clamp_lo_hi;
    int  i, p, mid, sign;
    int  ceil_val;

    for (i = 0; i < NUM_GOODS; ++i) {

        supply[i] = (long)(short)price_seed[i];

        for (p = 0; p < 4; ++p) {

#ifdef _VICEROY_MODERN
            extern uint8_t g_dgroup[];
            long h = *(int32_t *)(g_dgroup + g_power_table + p * 0x13C + 0xFC + i * 4);
#else
            long h = *(long *)((char *)(g_power_table + p * 0x13C) + 0xFC + i * 4);
#endif
            if (h < 0) h = 0;
            supply[i] += h;
        }

        if (arg_mode == 0 && g_active_power_index == 0) {
            long dec = supply[i] >> 8;
            price_seed[i] -= (short)dec;
        }
    }

    {
        long t = supply[9] + supply[10] + supply[11] + supply[12];
        if (t < 1) t = 1;
        S_pair = t;
    }

    for (i = 9; i <= 12; ++i) {
        if (good_filter >= 0 && i != good_filter)
            continue;

        if (supply[i] < 1) supply[i] = 1;

        clamp_lo_hi = ldiv32(S_pair * 3L, supply[i]);

        {
            int delta = (int)(signed char)PR_PRICE_LEVEL(g_market, i) - (int)clamp_lo_hi;
            sign = (delta > 0) ? 1 : (delta < 0) ? -1 : 0;
        }
        mid = ((int)(signed char)CARGO(i, 5) + (int)(signed char)CARGO(i, 6)) / 2;

        if (arg_mode != 0) {

            int lo = (signed char)CARGO(i, 2);
            int hi = (signed char)CARGO(i, 3);
            if ((int)clamp_lo_hi < lo) clamp_lo_hi = lo;
            if ((int)clamp_lo_hi > hi) clamp_lo_hi = hi;
            PR_PRICE_LEVEL(g_market, i) = (unsigned char)clamp_lo_hi;
        } else {
            PR_VOL_ACCUM(g_market, i) += (short)(sign * mid * 0x64);
        }
    }

    for (i = 1; i <= 4; ++i) {
        long v;
        if (good_filter >= 0 && i != good_filter)
            continue;
        v = supply[i];
        if (i == 4) v >>= 1;
        if (v < 1) v = 1;
        clamp_lo_hi = ldiv32(S_pair * 3L, v);
        if (i == 4) {
            if (g_market_year < 0x6A4) clamp_lo_hi += 1;
            if (g_market_year < 0x640) clamp_lo_hi += 1;
        }
        {
            int delta = (int)(signed char)PR_PRICE_LEVEL(g_market, i) - (int)clamp_lo_hi;
            sign = (delta > 0) ? 1 : (delta < 0) ? -1 : 0;
        }
        mid = ((int)(signed char)CARGO(i, 6) + (int)(signed char)CARGO(i, 5)) / 2;
        PR_VOL_ACCUM(g_market, i) += (short)(sign * mid);
    }

    for (i = 0; i < NUM_GOODS; ++i) {
        if (good_filter >= 0 && i != good_filter)
            continue;

        ceil_val = (signed char)CARGO(i, 3);

        if (i >= 0xE) {
            int gated = (g_active_power_index >= 4) ||
                        (power_is_ai[g_active_power_index * 0x34] == 0);
            if (gated) {
                int t = (g_market_year - 0x258) / 0x64;
                ceil_val += ((int)(signed char)difficulty - 4) * 2 + t;
                if (good_filter < 0  &&
                    PR_PRICE_LEVEL(g_market, i) > ceil_val) {
                    PR_VOL_ACCUM(g_market, i) +=
                        (short)((signed char)CARGO(i, 6) * 0x64);
                }
            }
        }

        {
            int up_step  = (signed char)CARGO(i, 7);
            int rise_thr = (int)(0x9C * (signed char)CARGO(i, 5));
            int fall_thr = (int)(0x64 * (signed char)CARGO(i, 6));

            if (g_active_power_index == 3 && (g_market_phase & 1))
                up_step *= 2;

            PR_VOL_ACCUM(g_market, i) += (short)up_step;

            if ((int)PR_VOL_ACCUM(g_market, i) >= rise_thr) {
                PR_VOL_ACCUM(g_market, i) -= (short)rise_thr;
                if (PR_PRICE_LEVEL(g_market, i) < ceil_val)
                    PR_PRICE_LEVEL(g_market, i)++;

                if (g_active_power_index < 4 &&
                    power_is_ai[g_active_power_index * 0x34] == 0) {
                    msg_set_arg(0, cargo_col0[i]);
                    msg_set_arg(1, nation_name[g_active_power_index]);
                    msg_emit_num(good_label_value(i), 0);
                    msg_show(2, 0xFA8 );
                }
            }

            if (fall_thr <= (int)PR_VOL_ACCUM(g_market, i)) {
                PR_VOL_ACCUM(g_market, i) -= (short)fall_thr;
                if (PR_PRICE_LEVEL(g_market, i) > (signed char)CARGO(i, 2))
                    PR_PRICE_LEVEL(g_market, i)--;
                if (g_active_power_index < 4 &&
                    power_is_ai[g_active_power_index * 0x34] == 0) {
                    msg_set_arg(0, cargo_col0[i]);
                    msg_set_arg(1, nation_name[g_active_power_index]);
                    msg_emit_num(good_label_value(i), 0);
                    msg_show(2, 0xFB0 );
                }
            }
        }

        if (good_filter >= 0)
            PR_VOL_ACCUM(g_market, i) -= (short)(signed char)CARGO(i, 7);

        {
            int hard_ceil = 0x19;
            if (i == 0xF || i == 0xE || i == 8) {
                int d = -((int)(signed char)difficulty - 4);
                hard_ceil = (d * 3) / 2 + 3;
                if (hard_ceil <= PR_PRICE_LEVEL(g_market, i))
                    hard_ceil = PR_PRICE_LEVEL(g_market, i);
                PR_PRICE_LEVEL(g_market, i) = (unsigned char)hard_ceil;
            }

            {
                int disp = (signed char)PR_PRICE_LEVEL(g_market, i) - 1;
                if (disp < 0) disp = 0;
                display_price[g_active_power_index * 0x10 + i] = (unsigned char)disp;
            }
        }
    }
}

void cargo_table_load(void)
{
    int good;

    names_open_section( 0x2252, 0);

    for (good = 0; good < 0x14; ++good) {
        names_next_record();

        cargo_col0[good] = names_read_int_word();

        if (good < NUM_GOODS) {

            CARGO(good, 0) = names_read_int_byte();
            CARGO(good, 1) = names_read_int_byte();
            CARGO(good, 2) = names_read_int_byte();
            CARGO(good, 3) = names_read_int_byte();
            CARGO(good, 4) = names_read_int_byte();
            CARGO(good, 5) = names_read_int_byte();
            CARGO(good, 6) = names_read_int_byte();
            CARGO(good, 7) = names_read_int_byte();
            CARGO(good, 8) = names_read_int_byte();
        }
    }

}

int market_ask_price(int good)
{
    int v = (int)(signed char)CARGO(good, 4)
          + (int)(signed char)PR_PRICE_LEVEL(g_market, good);
    return v < 0 ? 0 : v;
}

int market_bid_price(int good)
{
    int v = (int)(signed char)PR_PRICE_LEVEL(g_market, good) - 1;
    return v < 0 ? 0 : v;
}

long market_buy(int good, int qty)
{
    if (boycott_is_active(good) || qty <= 0) return 0;
    {
        long value = (long)market_ask_price(good) * qty;
        PR_GOLD(g_market) -= value;

        PR_VOL_ACCUM(g_market, good) -= (short)qty;
        return value;
    }
}

long market_sell(int good, int qty)
{
    if (boycott_is_active(good) || qty <= 0) return 0;
    {
        long gross = (long)market_bid_price(good) * qty;
        long tax   = gross * (long)(unsigned char)((unsigned char *)g_market)[0x01] / 100;

        long net   = gross - tax;
        PR_GOLD(g_market) += net;

        *(int32_t *)((char *)g_market + 0x22) += (int32_t)tax;
        *(int32_t *)((char *)g_market + 0x26) += (int32_t)net;
        PR_VOL_ACCUM(g_market, good) += (short)qty;
        return net;
    }
}

#include <stddef.h>
#include "viceroy_types.h"
#include <stddef.h>

extern uint8_t g_difficulty_53A6;

extern void *  g_king_record_84FC;
extern int16_t g_turn_counter_538E;

extern uint16_t ovly_181F_04D4(uint16_t lo, uint16_t hi);
extern void   ovly_181F_0998(void *buf, void *src, int16_t arg);

extern void   ovly_191F_0AE0(uint16_t delta, uint16_t str_off);

void king_attempt_tax_change(void)
{

    int16_t current_tax = *((int8_t *)g_king_record_84FC + 1);
    if (current_tax <= 1) goto do_kingraise;

    int16_t base_amount = ((g_difficulty_53A6 & 0xFE) * 2) + 4;

    int16_t era_mult = (g_turn_counter_538E / 400) + 1;

    int16_t proposed_change = base_amount * era_mult;

    if (proposed_change + 5 >= current_tax) goto do_kingraise;

    if ((int8_t)proposed_change >= current_tax) goto do_kingnothing;

    if (ovly_181F_04D4(1, g_difficulty_53A6 + 1) == 1) {

        uint16_t lower_amount = ovly_181F_04D4(1, 5 - g_difficulty_53A6);
        ovly_181F_0998(NULL, "KINGLOWER" , -(int16_t)lower_amount);
        return;
    }

do_kingnothing:
    {

        ovly_181F_0998((void*)0x087C, (const void*)0x109C, 0);
        return;
    }

do_kingraise:
    {

        uint16_t adjusted = ovly_181F_04D4(1, g_difficulty_53A6);
        adjusted *= 2;
        overlay_call_181F_04D4(1, (int16_t)DG8(g_difficulty));
        return;
    }
}

