    ADD(0x311, 3);
    ADD(0x312, 3);
    ADD(0x313, 3);
    ADD(0x314, 3);
    ADD(0x315, 3);
    ADD(0x316, 3);
    ADD(0x317, 3);
    SEP(0xFF, SEP_2B7, 3);
    ADD(0x320, 3);
    ADD(0x321, 3);
    ADD(0x322, 3);
    ADD(0x323, 3);
    SEP(0x100, SEP_2B8, 3);
    ADD(0x330, 3);
    SEP(0, SEP_2B9, 3);
    ADD(0x331, 3);
    ADD(0x332, 3);

    if (menu_add(0, MK_REPORTS) != 0) goto done;
    TITLE(4);
    ADD(0x40, 4);
    SEP(0, SEP_2C2, 4);
    ADD(0x41, 4);
    ADD(0x42, 4);
    ADD(0x43, 4);
    ADD(0x44, 4);
    SEP(0, SEP_2C3, 4);
    ADD(0x45, 4);
    ADD(0x46, 4);
    ADD(0x47, 4);
    ADD(0x48, 4);
    SEP(0, SEP_2C4, 4);
    ADD(0x49, 4);

    if (menu_add(0, MK_TRADE) != 0) goto done;
    TITLE(5);
    ADD(0x50, 5);
    ADD(0x51, 5);
    ADD(0x52, 5);

    if (menu_add(0, MK_CUP) != 0) goto done;
    TITLE(6);
    ADD(0x62, 6);
    ADD(0x63, 6);
    SEP(0, SEP_2CF, 6);
    ADD(0x65, 6);
    ADD(0x66, 6);
    SEP(0, SEP_2D0, 6);
    ADD(0x67, 6);
    ADD(0x68, 6);
    SEP(0, SEP_2D1, 6);
    {

        void *row69 = txt_lookup(0x69);
        menu_add_item(DS_SEG, row69, 6, g_menubar_seg, g_menubar_off);
    }
    ADD(0x6A, 6);
    SEP(0, SEP_2D2, 6);
    ADD(0x6B, 6);
    ADD(0x6C, 6);
    ADD(0x6F, 6);

    if ((g_cheat_flag_5383 & 0x20) == 0)
        menu_add_cheat_x(si, 6, g_menubar_seg, g_menubar_off);

    if (menu_add(0, MK_PEDIA) != 0) goto done;
    TITLE(7);
