void report_cell_xy_4col(int col, int row, int *xout, int *yout)
{
    *xout = col * 0x4C + 0x0A;
    *yout = (row > 1 ? -1 : 0) + row * 0x3C + 0x10;
}

void report_cell_xy_3col(int index, int *xout, int *yout)
{
    int col = (index + 1) % 3;
    int row = (index + 1) / 3;
    *xout = col * 0x69 + 0x17;
    *yout = (row > 1 ? -1 : 0) + row * 0x60 + 0x07;
}

