void hall_of_fame_render(void)
{
    char buf[0x60];
    int  rating;
    int  player = 0;
    int  rank_factor;
    int  score, i, sprite, saved_cursor;

    saved_cursor = g_cursor_372;
    g_cursor_372 = 0;

    if (hof_select_player(player) <= 0)
        { g_cursor_372 = saved_cursor; return; }

    rank_factor = g_diff_53A6 + 4;
    if (g_diff_53A6 >= 3) rank_factor++;
    if (g_diff_53A6 >= 4) rank_factor++;
    score = rank_factor  ;
    rating = 0;
    if (rating > 0x17) rating = 0x17;

    {
        uint32_t ok = hof_screen_load(0,
                          g_region_2DA8c[0], g_region_2DA8c[1],
                          g_region_2DA8c[2], g_region_2DA8c[3],
                          HOF_WOODPAN2);
        if (!ok) hof_screen_present(0);
    }

    hof_str_cpy(buf, HOF_SCORE_A);
    if (rating < 9) hof_str_cat(buf, HOF_DIGIT0);
    hof_str_cat_num(buf, 0, rating + 1);
    hof_commit(buf, 0, 0xFC, 5, 0, 0);

    for (i = 0; i <= rating; i++) {
        int color = (i == rating) ? 0xFC : 0xFE;
        hof_commit(buf, 0, color, 0xA0, 0xC3 - (i + 1) , 0);
    }

    hof_commit(buf, 0, 0xFC, 0x8C, 0x8E, 0x22);

    hof_box_rule(0, 0x140, 0xC8, 0, 0, 0);

    if (rating >= 0x17)      sprite = 0x24;
    else if (rating > 6)     sprite = 0x25;
    else                     sprite = 0x21;
    hof_score_sprite(sprite);

    hof_present();
    hof_wait_input();
    hof_to_video(0xA000, 0xFC00);
    g_cursor_372 = saved_cursor;
    (void)score; (void)rank_factor;
}

void hall_of_fame_table(void *new_entry)
{
    char table[HALLFAME_MAX * HALLFAME_REC_STRIDE];
    char rowbuf[0x52];
    void *fp;
    int  i, y, x;
    int  inserted = -1;

    fp = hof_fopen(HOF_MODE_RB, HOF_FILE_RB);
    if (fp) {
        (void)hof_fread(table, 1, 0xD2, fp);
        (void)hof_fclose(fp);
    }

    if (new_entry) {
        int16_t new_score = *(int16_t *)((char *)new_entry + 0x26);
        for (i = 0; i < HALLFAME_MAX; i++) {
            int16_t slot_score = *(int16_t *)(table + i * HALLFAME_REC_STRIDE + 0x26);
            if (slot_score < new_score) {
                int j;

                for (j = HALLFAME_MAX - 1; j > i; j--)
                    memcpy(table + j * HALLFAME_REC_STRIDE,
                           table + (j - 1) * HALLFAME_REC_STRIDE, HALLFAME_REC_STRIDE);

                memcpy(table + i * HALLFAME_REC_STRIDE, new_entry, HALLFAME_REC_STRIDE);
                inserted = i;
                break;
            }
        }
    }

    (void)hof_screen_load(0, g_region_2DA8c[0], g_region_2DA8c[1],
                          g_region_2DA8c[2], g_region_2DA8c[3], HOF_WOODPANL_B);

    y = 0x10;
    x = 0x0A;
    for (i = 0; i < HALLFAME_SHOWN; i++) {
        int color = (i == inserted) ? 1 : 0;

        rowbuf[0] = 0;
        hof_str_cat_num(rowbuf, 0, i + 1);
        hof_str_cat(rowbuf, HOF_SEP_L);
        hof_str_cat(rowbuf, HOF_SEP_R);
        hof_text_row(rowbuf, 0, x, y, color, (i == inserted));
        hof_title_band(0, x, y, 0x140, 0, rowbuf);
        y +=  8 + 2;
    }

    fp = hof_fopen(HOF_MODE_WB, HOF_FILE_WB);
    if (fp) {
        (void)hof_fwrite(table, 1, 0xD2, fp);
        (void)hof_fclose(fp);
    }
    (void)inserted;
}

int hall_of_fame_update(void)
{
    return SCREEN_HALL_OF_FAME;
}

void hallfame_write(void)
{
    hall_of_fame_table(0);
}

