void ff_acquire_dispatch(int power, int ff_id)
{
    unsigned p;
    int16_t save_8dc6;
    int i;

    save_8dc6 = DGS16(0x8DC6);
    ff_announce(power);

    if (ff_id >= 0) {

        cs_1095(1, ff_id, power);

        {
            int16_t handle = (int16_t)DG16(g_founding_father_table + (unsigned)ff_id * 6);
            power_set_flag(handle, 1);
        }

        if (DGS8(0x53A9 + (unsigned)ff_id) < 0)
            DG8(0x53A9 + (unsigned)ff_id) = (uint8_t)power;
    } else {

        uint8_t buf[0x50];
        cs_1086(buf, power);
        power_set_flag((int)(long)buf, 1);
    }

    if (power < 4 &&
        DG8(AI_CTRL_543F + (unsigned)power * 0x34) == 0) {

        int16_t handle = (int16_t)DG16(g_founding_father_table + (unsigned)power * 6);
        power_set_flag(handle, 0);
        power_set_flag(power_handle(power), 1);
        ui_sound_or_msg(3);

        ff_portrait_dialog((void *)0x087C, (void *)0x125A, 0);

        cs_1077(ff_id, power);
        ff_pre_b(ff_id);
        ff_pre_a(power);
    }

    p = DG16(g_current_power_ptr);
    DG8(p + 0x14) += 1;
    DG16(p + 0x12) = 0xFFFF;

    if (ff_id == FF_JAKOB_FUGGER) {
        DG16(p + 0x20) = 0;
    }

    if (ff_id == FF_LA_SALLE) {
        for (i = 0; i < DGS16(g_colony_count); i++) {
            unit_at(i);

            unsigned c = DG16(g_current_colony_ptr);
            if (DG8(c + 0x1A) == (uint8_t)power && DGS8(c + 0x1F) >= 3)
                colony_effect_id9(0, 1);
        }
    }

    if (ff_id == FF_JOHN_PAUL_JONES) {
        int arg = power - 0x18;

        int slot = unit_create(0x11, power, arg, arg);
        if (slot >= 0) {
            unsigned u = g_unit_table + (unsigned)slot * 0x1C;

            unsigned src = g_power_table + (unsigned)power * 0x13C + 0x32;
            DG8(u + 0x08) = 0;
            DG8(u + 0x09) = DG8(src + 0);
            DG8(u + 0x0A) = DG8(src + 1);
            DG8(u + 0x16) = 0;
        }
    }

    if (ff_id == FF_POCAHONTAS) {
        for (i = 0; i < 8; i++) {
            settle_at(i);

            int16_t alarm = (int16_t)-DGS16(DG16(g_active_tribe_data_ptr) + (unsigned)power * 2 + 0x46);
            if (alarm < 0)
                native_alarm_clear(0, alarm, power, i);
        }
        for (i = 0; i < DGS16(g_settlement_count); i++) {
            settle_at2(i);

            DGS16(DG16(g_active_settlement_ptr) + (unsigned)power * 2 + 0x0A) = 0;
        }
    }

    if (ff_id == FF_SIMON_BOLIVAR) {
        if (power < 4 &&
            DG8(AI_CTRL_543F + (unsigned)power * 0x34) == 0) {
            int v = DGS16(g_rebel_sentiment_meter) + 0x14;
            if (v > 0x64) v = 0x64;
            DGS16(g_rebel_sentiment_meter) = (int16_t)v;
        }
    }

    if (ff_id == FF_DE_BREBEUF) {
        for (i = 0; i < DGS16(g_settlement_count); i++) {
            settle_at2(i);
            unsigned s = DG16(g_active_settlement_ptr);
            if (DGS8(s + 5) >= 0 && (DG8(s + 5) & 0x0F) == (uint8_t)power)
                DG8(s + 5) |= 0x10;
        }
    }

    if (ff_id == FF_LAS_CASAS) {

        for (i = 0; i < DGS16(g_unit_count); i++) {
            unsigned u = g_unit_table + (unsigned)i * 0x1C;
            if ((DG8(u + 0x03) & 0x0F) != (uint8_t)power)
                continue;
            if (DG8(u + 0x02) == 0 && DG8(u + 0x17) == 0x1B)
                DG8(u + 0x17) = 0x1C;
        }

        for (int k = 0; k < DGS16(g_colony_count); k++) {
            unit_at(k);
            unsigned c = DG16(g_current_colony_ptr);
            if (DG8(c + 0x1A) != (uint8_t)power)
                continue;
            for (int m = 0; m < DGS8(c + 0x1F); m++) {
                if (unit_type_of(m) == 0x1B)
                    unit_set_type(0x1C, m);
            }
        }
    }

    if (ff_id == FF_CORONADO) {
        for (i = 0; i < DGS16(g_colony_count); i++) {
            unit_at(i);

            coronado_reveal(i, power);
        }
    }

    if (ff_id == FF_WILLIAM_BREWSTER) {
        unsigned pool = g_power_table + (unsigned)power * 0x13C + 0x02;
        for (i = 0; i < 3; i++) {
            if (DG8(pool + i) == 0x19 || DG8(pool + i) == 0x1A)
                DG8(pool + i) = 0x1C;
        }
    }

    unit_at(save_8dc6);
    ff_finish(1);

}

