int ff_era_band(void)
{
    int band = 0;
    if (DGS16(g_year) >= 0x640) band = 1;
    if (DGS16(g_year) >= 0x6a4) band += 1;
    return band;
}

int ff_weight_for_year(int ff_id, int year)
{
    int band;
    if (ff_id < 0 || ff_id >= 25) return 0;
    band = (year >= 1700) ? 2 : (year >= 1600) ? 1 : 0;
    switch (band) {
        case 0:  return FF_TABLE[ff_id].weight_1500;
        case 1:  return FF_TABLE[ff_id].weight_1600;
        default: return FF_TABLE[ff_id].weight_1700;
    }
}

int ff_is_available(int ff_id, int (*owned_test)(int ff_id))
{
    if (ff_id < 0 || ff_id >= 25) return 0;
    if (owned_test(ff_id)) return 0;

    int cat = FF_TABLE[ff_id].category;
    for (int j = 0; j < ff_id; j++) {
        if (FF_TABLE[j].category == cat && !owned_test(j))
            return 0;
    }
    return 1;
}

#define FF_MEM_BASE   g_founding_father_table
#define FF_MEM2_BASE  0x96E8

extern int     ff_owned(int ff_id, int power);

void ff_set_owned_bit(int power, int ff_id, int set)
{
    uint8_t  bit = (uint8_t)(1 << (ff_id & 7));
    unsigned off = g_power_table__ff_owned_bitmap[0]
                 + (unsigned)power * POWER_RECORD_STRIDE
                 + ((unsigned)ff_id >> 3);
    if (set)
        DG8(off) |= bit;
    else
        DG8(off) &= (uint8_t)~bit;
}

int ff_available(int ff_id, int power)
{
    if (ff_owned(ff_id, power) != 0)
        return 0;
    return 1;
}

extern int ff_category_band(int power);

int ff_count_offerable_in_cat(int power, int cat)
{
    int n = 0;
    int band;
    int ff;
    for (ff = 0; ff < 25; ff++) {
        if (ff_owned(ff, power))
            continue;
        if (DG8(FF_MEM_BASE + (unsigned)ff * 6 + 0x02) != (uint8_t)cat)
            continue;
        band = ff_category_band(power);
        if (DG8(FF_MEM_BASE + (unsigned)ff * 6 + 0x03 + (unsigned)band) != 0)
            n++;
    }
    return n;
}

int ff_count_owned_in_cat(int power, int cat)
{
    int n = 0;
    int ff;
    for (ff = 0; ff < 25; ff++) {
        if (!ff_owned(ff, power))
            continue;
        if (DG8(FF_MEM_BASE + (unsigned)ff * 6 + 0x02) == (uint8_t)cat)
            n++;
    }
    return n;
}

extern int ff_cat_candidate(int cat, int pw);

int ff_best_offer_category(int power)
{
    int best_id = -1;
    int best_score = -1;
    int i;
    unsigned pr = g_power_table + (unsigned)power * POWER_RECORD_STRIDE;
    if (DG8(pr + 0x14) >= 0x19)
        return FF_CAT_INDEPENDENCE;
    for (i = 0; i < 5; i++) {
        int s = ff_cat_candidate(i, power);
        if (s >= best_score) {
            best_score = s;
            best_id = i;
        }
    }
    return best_id;
}

