#define MSG_REBELUP50   0x1358
#define MSG_REBELUP     0x1362
#define MSG_REBELDOWN   0x136A

static inline uint8_t *sol_pct_cell(int power)
{
    uint8_t *base = (uint8_t *)POWER_BASE_8808;
    return base + (unsigned)power * POWER_STRIDE + POWER_SOL_PCT_OFF;
}

void sons_of_liberty_update(int power_id)
{

    int is_rebel_view;
    if (power_id == g_active_power_5398) {
        is_rebel_view = 1;
    } else if ((g_flags_5382 & 1) &&
               power_id == g_rebel_power_53D2) {
        is_rebel_view = 1;
    } else {
        is_rebel_view = 0;
    }

    if (g_flags_5382 & 1) {

        if (!is_rebel_view) return;

        {   extern int func_03E442_op_sz_146(uint16_t power);
            func_03E442_op_sz_146((uint16_t)power_id);
        }
        return;
    }

    if (is_rebel_view)
        sol_helper_3695(power_id);

    uint8_t pct = sol_recompute_pct(power_id);

    *sol_pct_cell(power_id) = pct;

    if (!is_rebel_view) return;

    g_sol_value_53D0 = pct;

    if (pct >= 0x32 && g_rebel_power_53D2 < 0)
        sol_mark_rebel_power();

    {
        const uint8_t *gate = (const uint8_t *)POWER_GATE_9410;
        if (gate[(unsigned)power_id] < 4)
            return;
    }

    if (g_sol_value_53D0 / 10 > g_sol_prev10_53D8) {
        ui_set_channel(3);
        ui_push_value(g_sol_value_53D0);
        ui_flash_power(g_active_power_5398, 0, 0);

        if (g_sol_value_53D0 >= 0x32)
            ui_show_message(1, MSG_REBELUP50);
        else
            ui_show_message(1, MSG_REBELUP);

    } else {

        if ((g_sol_value_53D0 + 4) / 10 >= g_sol_prev10_53D8)
            return;
        ui_set_channel(1);
        ui_push_value(g_sol_value_53D0);
        ui_flash_power(g_active_power_5398, 0, 0);
        ui_show_message(1, MSG_REBELDOWN);
    }

    g_sol_prev10_53D8 = g_sol_value_53D0 / 10;
}

