int16_t ai_unit_leaf(int16_t unit_index, int16_t tile_x, int16_t tile_y,
                     int16_t one, int16_t mode)
{
    int16_t r_d6 = -1;
    int16_t r_b0 = -1;
    int16_t r_60 = -1;
    int16_t soft_score = 0;
    int16_t unit_type;
    int16_t owner;
    int16_t moves;
    int16_t band_flag;
    int16_t tile_unit;
    int16_t eval;
    int16_t sub_mode = 0;
    int16_t eval_reject_flag = 0;

    int16_t atk_str = 0;
    int16_t def_str = 0;
    int16_t def_owner = 0;
    int16_t def_type = 0;
    int16_t def_band = 0;
    int16_t occ_owner = -1;
    int16_t roll;
    int16_t soft_record = 0;
    int16_t win_flag = 0;
    int16_t loser_unit;
    (void)one;

    r_d6 = r_b0 = r_60 = -1;

    unit_type = g_units_3144[unit_index][0x02];

    soft_score = ovly_finalize_unit_90C(unit_index)
               - g_units_3144[unit_index][0x05];

    if (mode != 0) {
        g_units_3144[unit_index][0x05] =
            (uint8_t)(g_units_3144[unit_index][0x05] + 3);
    }

    owner = g_units_3144[unit_index][0x03] & 0x0F;
    moves = g_units_3144[unit_index][0x06];

    band_flag = (unit_type >= 0x0D && unit_type <= 0x12) ? 1 : 0;

    tile_unit = ovly_tile_to_unit_7E0(tile_x, tile_y);
    eval = ovly_eval_target_5E70A(tile_unit);

    g_ai_scratch_8D00 = 0; g_ai_scratch_A156 = 0;
    g_ai_scratch_8D02 = 0; g_ai_scratch_A158 = 0;

    if (soft_score < 3) {
        soft_record = soft_score;

        if (mode != 0) {

            if (owner >= 4) goto abort_far;
            if (g_ai_personality_543F[owner][0x00] != 0)
                goto abort_far;

            ovly_msg_arg_9AE(soft_score, 0, 0);
            if (ovly_dialog_652(1, 0x1C06 ) - 1 != 0)
                goto abort_far;
        }

        if (soft_score == 2) g_ai_scratch_8D01 |= 1;

        if (soft_score == 1) g_ai_scratch_A156 |= 8;
    }

    if (mode != 0) ovly_clear_orders_934(unit_index);

    occ_owner = ovly_target_query_6BE(tile_x, tile_y);
    r_d6      = ovly_target_query_7BE(tile_x, tile_y);

    if (eval >= 0) {
        goto candidate_loop;
    }

    eval_reject_flag = 1;
    sub_mode = 1;
    if (r_d6 < 0) {
        ovly_debug_str_77E(1, tile_y, tile_x, "Bad defense");
        if (ovly_path_check_302(tile_x, tile_y) != 0)
            goto cleanup_far;

        return r_d6;
    }

    {
        int16_t alt = ovly_target_query_9F0(tile_x, tile_y);
        r_b0 = alt;
        if (alt < 0) { sub_mode = 2;  }
    }

    if (r_d6 >= 0) {
        int16_t pop, colonist, cls, stat;
        ovly_query_9E6(r_d6);
        pop = ( (uint8_t)((g_colony_ptr_8542 , 0)) );

        colonist = random_int_4D4(0, pop - 1);
        cls = ovly_query_C54(colonist);
        g_ai_scratch_8D03 |= 2;
        stat = ovly_query_2C6(cls);
        if (ovly_feasible_7B4(0x0C, 0) != 0) {

            stat = 0x4B;
            g_ai_scratch_8D03 |= 4;
        }
        {
            int16_t spawned = ovly_spawn_unit_A20(0, tile_x, tile_y,
                                                  0, stat);
            g_units_3144[spawned][0x17] = (uint8_t)cls;
            eval = spawned;
        }
        goto have_candidate;
    }

    {
        int16_t cls = 0x13;

        ovly_commit_A4C(r_b0);

        eval = ovly_spawn_unit_A20(0, tile_x, tile_y,
                                   0, 0);
        (void)cls;
    }

have_candidate:

candidate_loop:

    if (eval < 0) { sub_mode = 3;  goto reason; }

    def_owner = g_units_3144[eval][0x03] & 0x0F;
    def_type  = g_units_3144[eval][0x02];

    def_str = res_get_unit_strength_def_7D3E(eval, unit_index);

    def_band = (def_type >= 0x0D && def_type <= 0x12) ? 1 : 0;

    atk_str = res_get_unit_strength_7C2A(unit_index, 1);

    atk_str = (int16_t)(((int32_t)atk_str * (g_def_terrain_bonus_8D04 + 4)) >> 2);
    atk_str = (int16_t)((atk_str * 3) >> 1);

    if (owner < 4 && g_ai_personality_543F[owner][0x00] == 0)
        atk_str += (int16_t)(4 - (int16_t)g_difficulty_53A6);

    if (def_owner < 4 && g_ai_personality_543F[def_owner][0x00] == 0)
        def_str += (int16_t)(4 - (int16_t)g_difficulty_53A6);

    if (soft_record != 0)
        atk_str = (int16_t)(((int32_t)atk_str * soft_record) / 3);

    if (band_flag == 0 && def_band == 0
        && UT_AT(unit_type, 0x5236) > 1
        && UT_AT(def_type, UNIT_REFIT_TABLE_5235) < 2)
        def_str >>= 1;

    if (occ_owner < 0) {
        if (unit_type == 0x0B) {
            uint8_t ord = g_units_3144[eval][0x08];
            if ((ord == 5 || ord == 6) && def_owner >= 4) {

            } else {
                atk_str >>= 2; g_ai_scratch_8D01 |= 8;
            }
        }
        if (def_type == 0x0B) {
            uint8_t ord = g_units_3144[eval][0x08];
            if ((ord == 5 || ord == 6) && def_owner >= 4) {

            } else {
                g_ai_scratch_8D03 |= 8; def_str >>= 2;
            }
        }
    } else {

        if (def_type == 0x0B && owner >= 4) {
            g_ai_scratch_A158 |= 1; def_str <<= 1;
        }
    }

    if (owner == 2 && def_owner >= 4 && occ_owner >= 0) {
        atk_str += (int16_t)(atk_str >> 1);
        g_ai_scratch_8D01 |= 0x10;
    }

    if ((g_flags_5382 & 1) && owner < 4) {
        if (r_d6 >= 0) {

            if (owner == g_self_marker_53D2 || (g_flags_5382 & 2)) {
                g_ai_scratch_8D01 |= 0x80;
                atk_str += (int16_t)(atk_str >> 1);
            }
            {
                int16_t sol_pct, sol_flag;
                ovly_query_9E6(r_d6);
                sol_pct = colony_field_C86();
                if (owner == g_self_marker_53D2) {
                    sol_flag = 2;
                    sol_pct  = (int16_t)(100 - sol_pct);
                } else {
                    sol_flag = 4;
                }
                if (sol_pct != 0) {
                    g_ai_scratch_A156 |= (uint16_t)sol_flag;
                    atk_str += (int16_t)(((int32_t)sol_pct * atk_str) / 100);
                }
            }
        } else {

            if (owner == g_self_marker_53D2) {
                if (!is_tile_walkable_or_special(tile_x, tile_y))
                    atk_str += (int16_t)(((int32_t)g_difficulty_53A6 * atk_str) / 20);
            }
        }

        if (owner == g_self_marker_53D2)
            func_005F48_logic_sz_58((uint16_t)tile_x, (uint16_t)tile_y);
    }

    if (mode == 0) {
        if (eval_reject_flag != 0) ovly_postcombat_05C69C(0,0,0);
        return (int16_t)(((int32_t)atk_str << 3) / (def_str + 1));
    }

    if (g_difficulty_53A6 <= 1) {

        if (!((g_flags_5382 & 1) && r_d6 >= 0
              && unit_type >= 0x0D && unit_type <= 0x12)) {

            if (def_owner < 4 && g_ai_personality_543F[def_owner][0x00] == 0
                && g_turn_538E < 0x50 && r_d6 >= 0) {
                if (g_difficulty_53A6 != 0)
                    atk_str >>= 1;
                else
                    atk_str -= (int16_t)(atk_str >> 2);

                if (eval_reject_flag != 0 && g_difficulty_53A6 == 0)
                    atk_str = 0;
            }
        }

        if (def_owner < 4 && g_ai_personality_543F[def_owner][0x00] == 0) {
            if (owner < 4 || g_turn_538E < 0x50)
                atk_str >>= 1;
        }
    }

    if (g_difficulty_53A6 == 0 && owner < 4
        && g_ai_personality_543F[owner][0x00] == 0)
        atk_str <<= 1;

    if (r_d6 >= 0) {
        if (owner >= 4) {

        }
        if (def_owner < 4
            && g_ai_personality_543F[def_owner][0x00] == 0) {

        }
    }

    roll = random_int_4D4(1, (int16_t)(def_str + atk_str));
    win_flag = (roll <= atk_str) ? 1 : 0;

    if (owner >= 4 && def_owner < 4 && g_ai_personality_543F[def_owner][0x00] == 0
        && unit_type == 0x13 && def_type == 0x0B) {
        win_flag = 0;

    }

    loser_unit = (win_flag != 0)
               ? eval

               : unit_index;

    ovly_combat_apply_wrapper_05BE30(loser_unit, eval, occ_owner,
                                     g_units_3144[unit_index][0x01],
                                     g_units_3144[unit_index][0x00]);

    r_d6 = win_flag;

reason:

    return r_d6;

abort_far:

    return -1;

cleanup_far:

    return r_d6;
}

