#include "viceroy_types.h"
#include "unit.h"

extern int16_t  g_active_unit;

extern int16_t  g_ship_dest_status;

extern int16_t  g_ship_dest_aux;

extern unsigned char g_in_europe_flag;

extern int16_t  g_active_power;

extern unsigned char g_unit_stat[];

extern struct UnitRecord g_units[];
#define U(i)            (g_units[(i)])
#define U_X(i)          (U(i).map_x)
#define U_Y(i)          (U(i).map_y)
#define U_TYPE(i)       (U(i).type)
#define U_ORDERS(i)     (U(i).orders)

extern int naval_classify_dest(int unit_idx, int dx, int dy);

extern void ovl_popup_simple   (const char *key, void *p, int z);
extern int  ovl_yesno_dialog   (const char *key, int flag);
extern void ovl_unload_at      (int aux);
extern int  ovl_landfall_begin (int unit_idx);
extern int  ovl_landfall_next  (int prev_idx);
extern void ovl_msg_simple     (const char *key);
extern void ovl_sailhome_191f  (void);
extern void ovl_sailhome_fin   (int unit_idx);
extern void ovl_shipcombat_fx  (int x, int y, int a, int b, int c);
extern void ovl_landfall_unit  (int unit_idx, int dy, int dx);
extern void ovl_reveal_tile    (int x, int y);
extern int  ovl_fortify_accum  (int x, int y);
extern void ovl_post_landfall  (void);
extern void power_scan_mark(int power);

#define DEST_OK 0

extern int  power_scan_done(int power);
extern void power_scan_mark(int power);

int naval_move_arrive(int dx, int dy)
{
    int ret      = 1;
    int dest_x;
    int dest_y;
    int adj_idx;
    int choice;
    int done;
    int sx, sy;

    dest_x = U_X(g_active_unit) + dx;
    dest_y = U_Y(g_active_unit) + dy;

    if (naval_classify_dest(g_active_unit, dest_x, dest_y) != DEST_OK) {
        goto abort_move;
    }

    switch (g_ship_dest_status) {

    case 1:

        ovl_popup_simple("NODOCKS", (void *)0x87c, 0);
        ret = 1;
        return ret;

    case 2:
    case 3:

        choice = ovl_yesno_dialog(
                     (g_ship_dest_status == 2) ? "LANDFALL" : "LANDFALL2", 3);
        if (choice != 2) goto done;

        ovl_unload_at(g_ship_dest_aux);

        adj_idx = ovl_landfall_begin(g_active_unit);
        for (;;) {
            adj_idx = ovl_landfall_next(adj_idx);
            if (adj_idx < 0) goto abort_move;

            {
                int t = U_TYPE(adj_idx);
                int role = g_unit_stat[t * 14 + 8];
                if (role >= 0x63) continue;
            }
            U_ORDERS(adj_idx) = 0;

        }

    case 4:
    case 5:
        if (g_in_europe_flag & 1) {
            ovl_msg_simple("EUROPENOTLEAVE");
            choice = 2;
        } else {
            choice = ovl_yesno_dialog("SAILHOME", 0);
        }
        if (choice == 1) {
            ovl_sailhome_191f();
            ovl_sailhome_fin(g_active_unit);
            ret = 1;
            return ret;
        }
        if (g_ship_dest_status == 4) goto done;
        goto abort_move;

    case 6:

        ovl_shipcombat_fx(dest_x - 2, dest_y - 2, 5, 5, 1);
        ret = 1;
        return ret;

    case 7:

        ovl_yesno_dialog("SHIPCOMBAT", 0);
        ret = 1;
        return ret;

    case 8:
        ovl_yesno_dialog("SHIPLAKE", 0);
        ret = 1;
        return ret;

    case 9:
        ovl_yesno_dialog("LANDFIRST", 0);
        ret = 1;
        return ret;

    default:
        goto done;
    }

abort_move:

    ovl_landfall_unit(g_active_unit, dest_y, dest_x);
    ret = 0;

    ovl_reveal_tile(dest_x, dest_y);

    {
        unsigned char *scan = &g_unit_stat[0];
        (void)scan;
    }

    if (power_scan_done(g_active_power)) goto done;

    done = 0;
    sx   = dest_y - 1;

    for (; done == 0 && (dest_y + 1) >= sx; sx++) {
        for (sy = dest_x - 1; done == 0 && (dest_x + 1) >= sy; sy++) {
            if (ovl_fortify_accum(sx, sy) != 0) {

                power_scan_mark(g_active_power);
                done = 1;
                ovl_post_landfall();
                break;
            }
        }
    }

done:
    ret = ret;
    return ret;
}

