int func_04198E_find_adjacent_cell(uint16_t unit )
{
    int ubx = unit * UNIT_STRIDE;
    int cx0, cy0, tn;
    int found = 0;
    int r = 1;
    int sx, sy;
    int hit_x = 0, hit_y = 0;
    int ax;

    cx0 = U_X(ubx);
    cy0 = U_Y(ubx);
    tn  = U_TYPENAT(ubx) & 0x0F;

    sx = sy = 0;
    goto ring_top;

edgeA_step:
    sx += 2 * r;
edgeA_test:
    if (found) goto edgeA_incY;
    if ((r + cy0) < sx) goto edgeA_incY;
    if (func_00627A_op_sz_57((uint16_t)sy, (uint16_t)sx) == 0x1A) {
        ax = overlay_call_181F_0682();
        if (ax >= 0 && ax == tn) {
            found = 1; hit_y = sy; hit_x = sx;
        }
    }
    goto edgeA_step;
edgeA_incY:
    sy++;
ringB_setup:
    if (found) goto edgeC_setup;
    if ((r + cx0) <= sy) goto edgeC_setup;
    sx = cy0 - r;
    goto edgeA_test;

edgeC_setup:
    sy = r + cx0;
    sx = cy0 - r;
    goto edgeC_join;
edgeC_step:
    if ((r + cy0) < sx) goto edgeD_setup;
    if (func_00627A_op_sz_57((uint16_t)sy, (uint16_t)sx) == 0x1A) {
        ax = overlay_call_181F_0682();
        if (ax >= 0 && ax == tn) {
            found = 1; hit_y = sy; hit_x = sx;
        }
    }
    sx++;
edgeC_join:
    if (found == 0) goto edgeC_step;

edgeD_setup:
    sy = cx0 - r;
    sx = cy0 - r;
    goto edgeD_join;
edgeD_step:
    if ((r + cy0) < sx) goto ring_grow;
    if (func_00627A_op_sz_57((uint16_t)sy, (uint16_t)sx) == 0x1A) {
        ax = overlay_call_181F_0682();
        if (ax >= 0 && ax == tn) {
            found = 1; hit_y = sy; hit_x = sx;
        }
    }
    sx++;
edgeD_join:
    if (found == 0) goto edgeD_step;

ring_grow:
    r++;
ring_top:
    if (found) goto commit;
    if (DGS16(g_map_width) <= r) goto commit;

    sy = -(r - cx0);
    goto ringB_setup;

commit:
    if (found == 0)
        return 0;
    {
        int t = U_TYPENAT(ubx) & 0x0F;
        DG8(t - 0x6BAA)++;
        if (U_ORDER(ubx) != 2) {
            if (t < 4 && !IS_REF_POWER(t))
                U_ORDER(ubx) = 3;
            else
                U_ORDER(ubx) = 0x0B;
        }
        U_DESTX(ubx) = hit_x;
        U_DESTY(ubx) = hit_y;
        U_FLAG4B(ubx) = 0x45;
    }
    return 0;
}

