static int unit_step_toward(uint16_t unit )
{
    int ubx = unit * UNIT_STRIDE;
    int dx, dy;
    int c;
    int span;
    int e1;
    int e2;
    int found = 0;
    int lastA = 0, lastB = 0;
    int t;

    dx = U_DESTX(ubx);
    lastA = dx;
    dy = U_DESTY(ubx);
    lastB = dy;
    c = 0;
    span = dx - c;
    goto p1_test;

p1_substep:
    {
        int off;
        if (e1 < 0)        off = -c;
        else if (e1 == 0)  off = 0;
        else               off = c;
        off += dy;

        if (overlay_call_1A1F_0254() != 0) {
            found = 1;
            lastA = span; lastB = off;
        }
    }
    e1 += 2;
    if (e1 > 1) goto p1_advance;
    if (e1 == 0) goto p1_substep;
    if (e1 < 0)  goto p1_substep;
    goto p1_substep;
p1_advance:
    span++;
p1_test:
    if (found) goto p2_init;
    if ((c + dx) >= span) {
        e1 = -1;
        goto p1_substep;
    }

p2_init:
    e2 = dy - c;
    goto p2_test;
p2_substep:
    {
        int off;
        if (e2 < 0)        off = -c;
        else if (e2 == 0)  off = 0;
        else               off = c;
        off += dx;
        if (overlay_call_1A1F_0254() != 0) {
            found = 1;
            lastA = off; lastB = e2;
        }
    }

    e2 += 0;
p2_advance:

p2_test:
    if (found) goto post;
    if ((c + dy) >= e2) {
        e2 = -1;
        goto p2_substep;
    }

post:
    c++;
    if (found == 0) {
        int bound = DGS16(g_map_height);
        if (bound < DGS16(g_map_width))
            bound = DGS16(g_map_width);
        if (bound > c)
            goto p1_seed;
    }
    goto present;

p1_seed:
    span = dx - c;
    e1 = 0;
    goto p1_test;

present:
    if (found == 0) {
        int snd = overlay_call_181F_07E0();
        (void)snd;
        overlay_call_181F_083A();
    }
    overlay_call_181F_08DA();
    overlay_call_181F_0948();
    overlay_call_181F_084E(unit);
    overlay_call_181F_07A0(unit);

    t = U_TYPENAT(ubx) & 0x0F;
    if (t == G_HUMAN_POWER) {
        if (overlay_call_181F_0352() == 0) {

            overlay_call_181F_09BA();
        }
        overlay_call_181F_0E12();
    }
    (void)span; (void)e1; (void)e2; (void)lastA; (void)lastB;
    return 0;
}

