int native_add(int x, int y, int tribe)
{
    int idx;
    struct NativeSettlement *s;

    if (g_native_count >= NATIVE_SETTLEMENT_CAP)
        return -1;

    idx = (int)g_native_count;
    g_native_count++;

    s = &g_native_settlements[idx];
    s->x          = (uint8_t)x;
    s->y          = (uint8_t)y;
    s->owner      = (uint8_t)tribe;

    s->population = (uint8_t)native_roll_population(idx);
    s->mission    = 0xFF;

    return idx;
}

