#define REL_STATE_MATRIX_BASE   g_treaty_matrix_base
#define POWER_STRIDE            0x13C

#define MSGKEY_SIGNTREATY       0x188D
#define MSGKEY_CANCELTREATY     0x1898
#define MSGKEY_DECLAREWAR       0x18A5

#define NOTIFY_CHANNEL_TREATY   2

extern uint8_t rel_query(int power_self, int power_other);

extern int      power_handle(int power_idx);

extern void     power_set_flag(int handle, int flag);

extern void     ui_notify_key(int channel, int msg_key);

extern void     rel_apply_event(int mask, int power_a, int power_b);

extern void     rel_clear_event(int mask, int power_a, int handle);

extern int  cs_3f58(int a, int b);
extern void cs_3f30(int a, int b);

extern uint8_t  g_diplo_guard_5382;
extern int16_t  g_diplo_phase_538e;

extern struct PowerRecord *g_active_power;

static inline uint8_t *rel_state_cell(int power_self, int power_other)
{

    uint8_t *base = (uint8_t *)REL_STATE_MATRIX_BASE;
    return base + (unsigned)power_self * POWER_STRIDE + (unsigned)power_other;
}

void treaty_set_state(int a, int b)
{

    if (g_diplo_guard_5382 & 1)
        return;

    int phase = (a + g_diplo_phase_538e + b) % 3;

    if (phase != 0) {

        if (rel_query(a, b) & 0x20)
            return;

        if (rel_query(a, b) & 0x02)
            return;
    }

    if (rel_query(b, a) & 0x02)
        return;

    power_set_flag(power_handle(a), 0);
    power_set_flag(power_handle(b), 1);

    if (cs_3f58(b, a) || cs_3f58(a, b)) {

        if (!(rel_query(a, b) & 0x40)) {
            if (rel_query(a, b) & 0x20)
                return;
        }

        int key = (rel_query(a, b) & 0x40)
                      ? MSGKEY_CANCELTREATY
                      : MSGKEY_DECLAREWAR;
        ui_notify_key(NOTIFY_CHANNEL_TREATY, key);

        *rel_state_cell(a, b) = 0;
        *rel_state_cell(b, a) = 0;

        rel_clear_event(0x40, b, power_handle(b));
        return;
    }

    if (rel_query(a, b) & 0x40)
        return;

    ui_notify_key(NOTIFY_CHANNEL_TREATY, MSGKEY_SIGNTREATY);

    rel_apply_event(0x40, b, a);

    cs_3f30(b, a);
    cs_3f30(a, b);

    *rel_state_cell(a, b) = 1;
    *rel_state_cell(b, a) = 1;

}

