int func_04C5C0_ai_power_budget(uint16_t power)
{
    int v0   = (int8_t)g_ai_pwr_v0_9410[power];
    int tier = (int8_t)g_ai_pwr_tbl_9298[power];

    if (g_colony_count_539E >= 0x30)
        return 0;
    if (tier < 1)
        return 8;
    if (g_ai_pwr_gate_A0B8[power] == 0)
        return 8;

    int ratio = (int8_t)g_ai_pwr_ratio_9567[power];
    int denom = 4 - ratio;
    int acc   = (v0 - tier) / denom;

    int half = (int8_t)g_ai_pwr_scale_9414[power] >> 1;
    if (acc > half) {
        acc -= ((acc - half) + 1) >> 1;
    } else if (half > acc) {
        acc += ((half - acc) + 1) >> 1;
    }

    int t = 7 - 3 * ratio;
    int cap = (int16_t)g_ai_pwr_cap_944E[power];
    if (t > cap) {
        acc += (int)((0xFFFF - (t - cap)) * tier);
    }

    return (acc < 0) ? 0 : acc;
}

extern uint16_t g_ai_word_tbl_85C8[];
extern uint8_t  g_ai_byte_tbl_947E[];
extern uint8_t  g_ai_sub_tbl_94E6[];

int func_04C682_ai_power_strength_delta(uint16_t arg0, int16_t arg1)
{
    int acc = 0;
    if (arg1 < 0) return acc;

    int capacity = (int16_t)g_ai_word_tbl_85C8[arg1] / 12;
    int demand   = g_ai_byte_tbl_947E[arg1];
    for (int k = 0; k < 4; k++)
        demand += g_ai_sub_tbl_94E6[arg1 + k * 0x10];

    int d = capacity - demand;
    if (d > 0)      acc += 1;
    else if (d < 0) acc += -1;

    if (g_ai_byte_tbl_947E[arg1] == (uint8_t)demand)
        acc += 2;
    if (g_ai_sub_tbl_94E6[arg0 * 0x10] < 1)
        acc += 4;

    return acc;
}

int func_04C71C_ai_unit_task_priority(uint16_t power, uint16_t unit, uint16_t dest)
{
    int prio = 0;
    uint8_t *u = &g_unit_table_3144[unit * UNIT_RECORD_STRIDE];

    if (g_ai_pwr_tbl_9298[power] != 0) {
        int cost = overlay_call_181F_0614();
        if (cost >= 0)
            prio = ai_path_budget_8DB8() / 5 - 1;
        else
            prio = 2;
    }

    switch (u[UNIT_TYPE_OFF ]) {
        case 2: prio += 2; break;
        case 1: prio -= 2; break;
        case 4: prio -= 3; break;
        case 0:
            prio -= 2;
            if (overlay_call_181F_0C9A() != 0)
                prio -= 2;
            break;
        default: break;
    }
    if (u[0x17 ] == 0x1B)
        prio -= 0x14;

    if (ovly_tramp_7A80(power) != 0) {
        int16_t turn = ai_turn_counter_538E();
        int16_t last = *(int16_t *)&g_power_table_8808[power * 0x13C + 0x46];
        prio += (turn - last) >> 4;
    }

    return (prio > 0) ? 0 : prio;
}

