        if (overlay_call_181F_0302() == 0) {  }

        else if (overlay_call_181F_0768() != 0) {  }
        else {

            int terr = func_00627A_op_sz_57((uint16_t)dy, (uint16_t)dx);
            score = g_terrcost_2F77[terr * 0x10];

            for (int k = 0; k < 8; k++) {
                if (overlay_call_181F_0302() == 0) continue;
                if (overlay_call_181F_0768() != 0) continue;
                int pcost = overlay_call_181F_0682();
                if (pcost >= 0) continue;
                int owner = overlay_call_181F_06DC();
                if (owner >= 0 && owner < 4 &&
                    g_ai_personality_540E[owner * 0x34 + 0x31] == 0 &&
                    (overlay_call_181F_0A38() & 0x40)) {
                    continue;
                }
                if (flag != 0) {

                    int h = func_005E90_op_sz_64((uint16_t)dx, (uint16_t)dy);
                    int s = (ovly_tramp_7A99((uint16_t)h, power) << 4)
                            + (overlay_call_181F_074A() & 0xF);
                    score += s;
                }
            }
        }

        if (score > best) {
            best = score;
            best_dir = dir;
        }

