extern uint8_t  g_demo_flag;

extern uint8_t g_dgroup[];
#define ACTIVE_POWER_REC()  ((uint16_t)(g_dgroup[g_current_power_ptr] | (g_dgroup[0x84FD] << 8)))

extern uint8_t g_power_metric_6D68[];

void gold_income_tick_for_power(int power_idx)
{
    long v, acc;
    int  diff;

    v = (long)g_power_metric_6D68[power_idx]
        + ((int)g_year - 0x5DC) / 50;

    if (g_turn < 0x14)
        v = 0;

    if (g_year >= 0x6A4)
        v <<= 1;

    diff = g_difficulty;
    acc = v * diff;
    if (diff == 3) acc += acc >> 1;
    else if (diff == 4) acc <<= 1;
    acc <<= 2;

    {
        uint16_t rec = ACTIVE_POWER_REC();
        int32_t gold = (int32_t)(g_dgroup[rec + 0x2A]
                     | (g_dgroup[rec + 0x2B] << 8)
                     | ((uint32_t)g_dgroup[rec + 0x2C] << 16)
                     | ((uint32_t)g_dgroup[rec + 0x2D] << 24));
        gold += (int32_t)acc;
        g_dgroup[rec + 0x2A] = (uint8_t)(gold       & 0xFF);
        g_dgroup[rec + 0x2B] = (uint8_t)((gold >> 8) & 0xFF);
        g_dgroup[rec + 0x2C] = (uint8_t)((gold >> 16) & 0xFF);
        g_dgroup[rec + 0x2D] = (uint8_t)((gold >> 24) & 0xFF);
    }
    (void)power_idx; (void)g_colony_count; (void)g_demo_flag;
}

extern int raw_power_score(int arg);

int score_endgame_rank(int raw_score)
{
    int factor;
    long pct;
    int rank;
    int k;

    factor = (int)g_difficulty + 4;
    if (g_difficulty >= 3) factor++;
    if (g_difficulty >= 4) factor++;

    if (raw_score == 0)
        return -1;

    pct = ((long)factor * (long)raw_score) / 100;

    rank = -1;
    for (k = 1; k <= 0x18; k++) {
        if (((long)k * k) / 3 < pct)
            rank = k - 1;
    }

    if (rank > 0x17) rank = 0x17;
    return rank;
}

int32_t power_current_gold(int power_idx)
{

    extern uint8_t g_power_table[];
    return *(int32_t *)(g_power_table + power_idx * POWER_RECORD_STRIDE + 0x2A);
}

