            int16_t mult = pool;

            if (overlay_call_181F_07B4() == 0) {
                int16_t player_floor = (int16_t)((U8(g_difficulty) + 10) * 5);
                int16_t pool_doubled = (int16_t)(mult * 2);
                mult = (player_floor >= pool_doubled) ? player_floor
                                                      : pool_doubled;
            }
            if (mult > 90) mult = 90;

            gold_delta = aFldiv(aFlmul((int32_t)mult, (int32_t)base_amount), 100);

            overlay_call_181F_09AE();
            overlay_call_181F_09AE();
            overlay_call_181F_09AE();
