    overlay_call_181F_09A4();
    overlay_call_181F_0438();
    overlay_call_181F_04B6(2);
    overlay_call_181F_0652(0x1bfd, 2);

    DGS32(attacker_power * 0x13C + g_power_table__royal_money) += gold_delta;

carry_only:
    {

        int32_t carry = (int32_t)((int16_t)base_amount - (int16_t)gold_delta);
        DGS32(attacker_power * 0x13C + g_power_table__gold) += carry;
        DGS32(attacker_power * 0x13C + g_power_table__royal_money_p4) += carry;
    }

