#define UREC(i, off)  DG8(g_unit_table + (i)*0x1C + (off))

static int colonist_prof_cell(int prof)
{
    switch (prof) {
    case 0x13: return 0x65;
    case 0x14: return 0x3B;
    case 0x15: return 0x3C;
    case 0x16: return 0x3D;
    case 0x18: return 0x3E;
    case 0x19: return 0x6B;
    case 0x1A: return 0x6C;
    case 0x1B: return 0x43;
    case 0x1C: return 0x65;
    default:   return prof + 0x52;
    }
}

static int unit_cell(int idx)
{
    int rec  = idx * 0x1C;
    int type = DG8(UNIT_TYPE + rec);
    int cell = DG8(0x5232 + type * 14);
    int prof = (int8_t)DG8(g_unit_table__vet_type + rec);
    if (type == 0)
        cell = colonist_prof_cell(prof);
    if (type == 2 && prof != 0x14) cell = 0x4A;
    if (type == 1 && prof != 0x15) cell = 0x4B;
    if (type == 4 && prof != 0x15) cell = 0x4D;
    if (type == 5 && prof != 0x16) cell = 0x4C;
    if (type == 3 && prof != 0x18) cell = 0x4E;
    if (type == 0xB && (DG8(U_FLAGS_3148 + rec) & 0x80))
        cell = 0x42;
    return cell;
}

static int unit_display_record(int idx, int flags, int *out)
{
    int pick = idx;
    if (flags & 0x40) {
        int ship = -1;
        int cur  = unit_chain_resolve(idx);
        while (cur >= 0) {
            int t = UREC(cur, 2);
            if (t >= 0xD && t <= 0x12) ship = cur;
            cur = unit_chain_next(cur);
            if (ship >= 0) break;
        }
        if (ship >= 0) pick = ship;
    }
    *out = pick;
    return unit_cell(pick);
}

void unit_figure_blit_64(int unit, int flags, int x, int box_w, int y)
{
    char buf[2];
    int rec_idx, rec, type, owner, orders, cls;
    int rebel_x = 0;
    int stacked = 0;
    int cell, ch, boxcol, digit;
    int label_w, label_h, fig_w, fig_h, total_w;
    int dx, fig_x, label_x, label_y, box_x, box_y;

    flags &= ~0x20;
    cell = unit_display_record(unit, flags & 0x40, &rec_idx);

    if (flags & 0x80)
        stacked = (unit_chain_next(unit_chain_resolve(unit)) >= 0);

    rec  = rec_idx * 0x1C;
    type = DG8(UNIT_TYPE + rec);

    cls = 0;
    if (type >= 0xD && type <= 0x12)
        cls = (type >= 0xF) ? 1 : 3;
    else if (type == 0x15 || type == 0x16 || type == 5 ||
             type == 4 || type == 7 || type == 8)
        cls = 3;
    else if (type == 0xC || type == 0xA || type == 0xB) {
        cls = 2;
        if (type == 0xB && (DG8(U_FLAGS_3148 + rec) & 0x80))
            cls = 4;
    }

    owner  = DG8(UNIT_OWNER + rec) & 0xF;
    orders = DG8(U_ORDERS_314C + rec);
    if (owner >= 4) orders = 0;
    ch = DG8(0x54DE + orders);

    if (type >= 0xD && type <= 0x12 &&
        (int16_t)DG16(g_active_human_player) != owner) {
        ch = '0' + DG8(UNIT_CARGO_3150 + rec);
        if (type == 0x10 && DG16(0x53A2) == 0) {
            rebel_x = 1;
            ch = 'X';
        }
    }

    if (owner < 4 &&
        DG8(AI_CTRL_543F + owner * 0x34) != 0 &&
        (DG8(0x5383) & 0x20) &&
        (DG8(0x0894) & 8)) {
        ch = DG8(g_unit_table__profession + rec);
        if (ch >= 0x80) ch = 'E';
    }

    boxcol = DG8(0x848 + owner);
    {
        int txtcol = boxcol;
        if (rebel_x) txtcol = 0;

        digit = ((DG8(U_FLAGS_3148 + rec) & 0x80) && type != 0xB);
        if (digit) {
            int s = DG8(UNIT_REFIT_TABLE_5235 + type * 14)
                  - DG8(U_TURN_315A + rec);
            if (is_xy_in_map_bounds(DG8(g_unit_table + rec), DG8(UNIT_Y + rec)))
                s = (s + 1) >> 1;
            ch = (s < 10) ? '0' + s : '+';
        }

        buf[0] = (char)ch; buf[1] = 0;
        label_w = vid_text_width(buf) + 3;
        label_h = vid_text_ctx_byte0() + 3;
        fig_w   = sheet_frame_w_icons(cell);
        fig_h   = sheet_frame_h_icons(cell);
        total_w = label_w + fig_w;

        dx = x;
        if (box_w > total_w)
            dx += (box_w - total_w) >> 1;

        fig_x = dx;
        dx += fig_w;
        if (total_w > 0x10)
            dx -= total_w - 0x10;

        switch (cls) {
        default:
            box_x   = dx - 2;
            label_y = y - label_h + fig_h;
            box_y   = label_y - 2;
            label_x = dx;
            cls = 0;
            break;
        case 1:
            box_x   = dx - 2;
            label_y = y;
            box_y   = y + 2;
            label_x = dx;
            cls = 0;
            break;
        case 2: case 4:
            label_x = fig_x - (label_w >> 1) + 9;
            label_y = y + ((cls == 4) ? 2 : 0);
            box_x   = label_x - 2;
            box_y   = label_y + 2;
            cls = 1;
            break;
        case 3:
            label_x = fig_x;
            label_y = y;
            box_x   = fig_x + 2;
            box_y   = y + 2;
            cls = 1;
            fig_x  += label_w;
            if (total_w + 2 > 0x10)
                fig_x -= total_w - 0xE;
            break;
        }

        if (cls != 0)
            blit_sprite_shadowed(1, cell, fig_x, y);
        if (stacked) {
            vid_box_fill(box_x, box_y, label_w, label_h, 0);
            vid_box_fill(box_x + 1, box_y + 1, label_w - 2, label_h - 2,
                         (uint8_t)txtcol);
        }
        vid_box_fill(label_x, label_y, label_w, label_h, 0);
        vid_box_fill(label_x + 1, label_y + 1, label_w - 2, label_h - 2,
                     (uint8_t)txtcol);
        if (cls == 0)
            blit_sprite_shadowed(1, cell, fig_x, y);
        blit_sprite_shadowed(2, cell, fig_x, y);
    }

    {
        int chcol;
        if (orders == 1 || orders == 6)
            chcol = (owner < 4) ? boxcol - 8 : 8;
        else
            chcol = 0;
        if (rebel_x) chcol = 0xF;
        if (digit)   chcol = (owner == 2) ? 0xC : 0xF;
        vid_text_color(chcol);
        vid_text_xy(buf, label_x + 2, label_y + 2);
    }
    if (digit)
        blit_sprite(0, 0x38, fig_x + 4, y + 4);
}

void unit_render_386A(int idx, int flags, int sx, int sy, int metric)
{
    int rec_idx;
    int cell = unit_display_record(idx, flags, &rec_idx);
    int type  = UREC(rec_idx, 2);
    int owner = UREC(rec_idx, 3) & 0x0F;

    char badge = 0;
    int  pri = 0;
    if (type >= 0xD && type <= 0x12) pri = (type >= 0xF) ? 1 : 3;
    else if (type == 0x15 || type == 0x16 ||
             type == 4 || type == 5 || type == 7 || type == 8) pri = 3;
    else if (type == 0xA || type == 0xB || type == 0xC) pri = 2;
    if (type == 0xB && (UREC(rec_idx, 4) & 0x80)) pri = 4;

    if (type >= 19 && type <= 23) {
        int cls = UREC(rec_idx, 8);
        if (cls >= 4) cls = 0;
        badge = (char)DG8(0x54DE + cls);
    }

    if ((UREC(rec_idx, 4) & 0x80) && type != 0xB) {
        int s = (int8_t)DG8(UNIT_REFIT_TABLE_5235 + type * 14)
              - (int8_t)UREC(rec_idx, 0x16);

        s = (s + 1) >> 1;
        badge = (char)(s < 10 ? '0' + s : '+');
    }

    vid_cell_blit(cell, sx + 8, sy + 7, metric, sx + 15);

    {
        int bx = sx, by = sy;
        if (pri == 1) { bx = sx + 1; by = sy + 1; }
        else if (pri == 3) { bx = sx + 5; by = sy + 5; }
        vid_small_box(bx, by, 2, DG8(0x848 + owner));
    }

    if (badge) {
        char b[2] = { badge, 0 };
        vid_text_color((flags & 0x20) ? 0x0F : DG8(0x848 + owner));
        vid_text_xy(b, sx + 11, sy + 3);
    }
}

void func_0673CC_unit_redraw(int idx, int mode, int flag2)
{
    if (mode && !flag2) return;
    int flags = 0x80 | ((mode != 1) ? 0x40 : 0)
              | (((UREC(idx,3) & 0x0F) != (int16_t)DG16(g_active_human_player)) ? 0x20 : 0);
    int sx = ((int)UREC(idx,0) - (int16_t)DG16(g_viewport_origin_x) + (int16_t)DG16(G_PIXBASE_COL))
             * (int16_t)DG16(G_TILE_PX);
    int sy = ((int)UREC(idx,1) - (int16_t)DG16(g_viewport_origin_y) + (int16_t)DG16(G_PIXBASE_ROW))
             * (int16_t)DG16(G_TILE_PX2) + 8;
    unit_render_386A(idx, flags, sx, sy - 8, (int16_t)DG16(0x0186));
}

void overlay_pass_units(void)
{
    int x0 = (int16_t)DG16(g_viewport_origin_x), y0 = (int16_t)DG16(g_viewport_origin_y);
    int x1 = x0 + (int16_t)DG16(G_SPAN_W) - 1, y1 = y0 + (int16_t)DG16(G_SPAN_H) - 1;
    int n = (int16_t)DG16(g_unit_count);
    for (int i = 0; i < n; i++) {
        int ux = UREC(i,0), uy = UREC(i,1);
        if (ux < x0 || ux > x1 || uy < y0 || uy > y1) continue;

        if ((int16_t)DG16(g_unit_table + i*0x1C + 0x18) >= 0) continue;
        func_0673CC_unit_redraw(i, 0, 1);
    }
}

