#define REF_SLOT(n) (*(&g_ref_regulars_53DA + (n)))

extern uint8_t  g_difficulty_53A6;
extern int16_t  g_year_538A;
extern void *   g_king_record_84FC;

void king_ref_init(void)
{
    int d = g_difficulty_53A6;
    g_ref_regulars_53DA  = d * 8 + 15;
    g_ref_cavalry_53DC   = (d + 1) * 5;
    g_ref_artillery_53E0 = d * 6 + 2;
    g_ref_manowar_53DE   = d * 3 + 2;
}

void king_register_ref_unit(int slot) { (void)slot; }

extern int      revolution_flag_5382(void);
extern int32_t *king_sentiment_accum_22(void);

void king_ref_buildup(int active_power)
{

    if (revolution_flag_5382() & 1) return;

    int32_t inc = (int32_t)g_difficulty_53A6 * 8 + 10;
    if (g_year_538A >= 0x640) inc *= 2;
    if (g_year_538A >= 0x6A4) inc *= 2;
    if (g_year_538A >= 0x6D6) inc *= 2;

    int32_t *accum = king_sentiment_accum_22();
    *accum += inc;
    if (*accum < 0x708) return;

    int reg = g_ref_regulars_53DA;
    int cav = g_ref_cavalry_53DC;
    int art = g_ref_artillery_53E0;
    int mow = g_ref_manowar_53DE;

    int slot = 0;
    if ((reg + 2) / 3 > cav)                  slot = 1;
    if (reg / 4       > art)                  slot = 3;
    if ((reg + cav + art + 5) / 10 > mow)     slot = 2;

    REF_SLOT(slot) += 1;
    *accum -= 0x708;

    DGS16(DG16(g_current_power_ptr) + 0x0E) +=
        (int16_t)(uint8_t)DG8((uint16_t)((uint16_t)active_power + 0x9408u));
}

